/**
 * Traduce el error de `getUserMedia` (o la falta de la API) a un mensaje para el afinador.
 *
 * Antes todo lo que no fuera `NotAllowedError` salía como "No se pudo abrir el micrófono", y
 * `NotAllowedError` como "Sin permiso de micrófono" aunque el permiso de Android estuviera
 * concedido (en el APK, el WebView también lanza `NotAllowedError` cuando Capacitor deniega la
 * petición por un permiso del manifiesto que falta). Ver la memoria
 * `bug-afinador-sin-permiso-apk`.
 */
export function micErrorMessage(error: unknown, isNativeApp: boolean): string {
  const name = errorName(error)
  switch (name) {
    case 'NotAllowedError':
    case 'PermissionDeniedError':
      return isNativeApp
        ? 'Sin permiso de micrófono: actívalo en Ajustes > Apps > Laudes > Permisos'
        : 'Sin permiso de micrófono: permítelo en el navegador'
    case 'SecurityError':
      return 'El navegador bloquea el micrófono en esta página'
    case 'NotFoundError':
    case 'DevicesNotFoundError':
    case 'OverconstrainedError':
      return 'No se encuentra ningún micrófono'
    case 'NotReadableError':
    case 'TrackStartError':
    case 'AbortError':
      return 'El micrófono está ocupado por otra app'
    case 'NoMediaDevices':
      return 'Este navegador no deja usar el micrófono'
    default:
      return 'No se pudo abrir el micrófono'
  }
}

function errorName(error: unknown): string {
  if (error && typeof error === 'object' && 'name' in error && typeof error.name === 'string') {
    return error.name
  }
  return ''
}
