<script setup lang="ts">
// Hoja inferior del modo edición de estrofas: Lucas toca una estrofa del himno, de un salmo o de un
// cántico y aquí la reparte él mismo (nota de voz del 02/11/2026; salmos y cánticos desde el
// 09/11/2026). Cada cambio se guarda al instante y se ve en el texto de detrás.
//
// 14/11/2026: «Unir» canta dos versículos con la misma voz (rayita verde); lo que antes hacía (dos
// líneas de texto en una) pasa a «Juntar». Y la hoja dice siempre si está guardado y dónde, con un
// botón «Guardar» bien a la vista (Lucas no encontraba dónde confirmar).
import { computed, ref } from 'vue'
import {
  Check,
  CloudCheck,
  CloudOff,
  CloudUpload,
  Copy,
  Group,
  Link2,
  Merge,
  RotateCcw,
  Scissors,
  SeparatorHorizontal,
  Slash,
  Undo2,
  Ungroup,
} from '@lucide/vue'
import {
  cycleLabel,
  displayWords,
  flattenLayout,
  isLineTogether,
  isJoinedWithNext,
  joinLines,
  layoutAsTableEntry,
  splitLine,
  toggleJoinWithNext,
  toggleLineTogether,
  togglePassRestart,
  toggleVoiceSplit,
  voiceSplitPosition,
  type EditableMode,
  type StanzaLayout,
} from '../lib/stanza-edit'
import { flushStanzaEditsSave, saveStanzaEdit, stanzaEdits, stanzaEditsCloud } from '../lib/stanza-edit-store'

export interface EditableStanza {
  key: string
  mode: EditableMode
  layout: StanzaLayout
  verses: string[]
}

const props = defineProps<{ stanza: EditableStanza }>()
const emit = defineEmits<{ (event: 'close'): void }>()

const layout = ref<StanzaLayout>(props.stanza.layout)
const history = ref<StanzaLayout[]>([])
const selected = ref(0)
/** Palabras antes del punto elegido en la línea seleccionada (0: ninguno). */
const cut = ref(0)
const copied = ref(false)

const flat = computed(() => flattenLayout(layout.value))
const selectedWords = computed(() => displayWords(flat.value[selected.value]?.text ?? ''))
const selectedSplit = computed(() => voiceSplitPosition(flat.value[selected.value]?.text ?? ''))
const isEdited = computed(() => Boolean(stanzaEdits.value[props.stanza.key]))
const canJoin = computed(() => selected.value < flat.value.length - 1)
const canCut = computed(() => cut.value > 0 && cut.value < selectedWords.value.length)
/** La línea elegida y la siguiente ya cantan con la misma voz: el botón pasa a «Desunir». */
const joinedWithNext = computed(() => isJoinedWithNext(layout.value, selected.value))
/** Líneas de un grupo de varias (la rayita verde), para pintarla también en la hoja. */
const mergedLines = computed(() =>
  flat.value.map((line, index) => !line.newGroup || Boolean(flat.value[index + 1] && !flat.value[index + 1].newGroup)),
)
/** Lo que dice la hoja sobre el guardado: en el dispositivo siempre; la nube, según vaya. */
const saveStatus = computed(() => {
  if (!history.value.length && !isEdited.value) {
    return { icon: Check, text: 'Sin cambios' }
  }
  if (stanzaEditsCloud.value === 'al-dia') {
    return { icon: CloudCheck, text: 'Guardado en la nube' }
  }
  if (stanzaEditsCloud.value === 'sin-conexion') {
    return { icon: CloudOff, text: 'Guardado aquí; la nube, luego' }
  }
  return { icon: CloudUpload, text: 'Guardado aquí; subiendo…' }
})

function apply(next: StanzaLayout, nextSelected = selected.value): void {
  if (next === layout.value) {
    return
  }
  history.value = [...history.value, layout.value]
  layout.value = next
  selected.value = Math.min(nextSelected, next.lines.length - 1)
  cut.value = 0
  saveStanzaEdit(props.stanza.key, next)
}

function selectLine(index: number): void {
  selected.value = index
  cut.value = 0
}

function chooseCut(wordIndex: number): void {
  // Tocar la palabra elige el punto que queda justo DESPUÉS de ella; volver a tocarla lo quita.
  cut.value = cut.value === wordIndex + 1 ? 0 : wordIndex + 1
}

const join = () => apply(toggleJoinWithNext(layout.value, selected.value, props.stanza.mode))
const joinText = () => apply(joinLines(layout.value, selected.value))
const split = () => apply(splitLine(layout.value, selected.value, cut.value, props.stanza.mode), selected.value + 1)
const passRestart = () => apply(togglePassRestart(layout.value, selected.value))
const voiceSplit = () => apply(toggleVoiceSplit(layout.value, selected.value, cut.value))
/** La línea como se lee, con la rayita de verso partido a la vista (sin `=`, `_` ni `$`). */
const shownLine = (text: string) => text.replace(/^=/, '').replace(/[_$]/g, '')
const together = () => apply(toggleLineTogether(layout.value, selected.value))
const label = (index: number) => {
  selected.value = index
  apply(cycleLabel(layout.value, index, props.stanza.mode), index)
}

function undo(): void {
  const previous = history.value[history.value.length - 1]
  if (!previous) {
    return
  }
  history.value = history.value.slice(0, -1)
  layout.value = previous
  selected.value = Math.min(selected.value, previous.lines.length - 1)
  cut.value = 0
  saveStanzaEdit(props.stanza.key, previous)
}

/** «Guardar»: cada cambio ya está guardado en el dispositivo; esto sube ya a la nube lo pendiente y
 * cierra la hoja. */
function done(): void {
  flushStanzaEditsSave()
  emit('close')
}

function reset(): void {
  saveStanzaEdit(props.stanza.key, undefined)
  emit('close')
}

async function copyForTable(): Promise<void> {
  try {
    await navigator.clipboard.writeText(layoutAsTableEntry(props.stanza.mode, props.stanza.verses, layout.value))
    copied.value = true
    window.setTimeout(() => (copied.value = false), 1800)
  } catch {
    // Sin portapapeles (http sin permiso): no pasa nada, el reparto ya está guardado.
  }
}
</script>

<template>
  <div class="stanza-editor" role="dialog" aria-label="Editar estrofa">
    <div class="stanza-editor-head">
      <div class="stanza-editor-title">
        <strong>Estrofa a {{ stanza.mode }} voces</strong>
        <span class="stanza-editor-status" :class="`is-${stanzaEditsCloud}`" role="status">
          <component :is="saveStatus.icon" :size="14" aria-hidden="true" /> {{ saveStatus.text }}
        </span>
      </div>
      <button type="button" class="stanza-editor-done" aria-label="Guardar y cerrar" @click="done">
        <Check :size="18" /> Guardar
      </button>
    </div>

    <ol class="stanza-editor-lines">
      <li
        v-for="(line, index) in flat"
        :key="index"
        :class="{
          'is-selected': index === selected,
          'has-pass-restart': line.newPass,
          'is-continued': !line.newGroup,
          'is-together': isLineTogether(line.text),
          'is-merged': mergedLines[index],
        }"
      >
        <button
          type="button"
          class="stanza-editor-label"
          :aria-label="`Voz ${line.label || 'sin rótulo'}; tocar para cambiarla`"
          @click="label(index)"
        >
          {{ line.newGroup ? line.label || '–' : '·' }}
        </button>
        <button type="button" class="stanza-editor-text" @click="selectLine(index)">{{ shownLine(line.text) }}</button>
      </li>
    </ol>

    <div class="stanza-editor-words" aria-label="Elige el punto de corte">
      <button
        v-for="(word, wordIndex) in selectedWords"
        :key="wordIndex"
        type="button"
        class="stanza-editor-word"
        :class="{
          'is-cut': cut === wordIndex + 1,
          'has-split': selectedSplit === wordIndex + 1,
        }"
        :disabled="wordIndex === selectedWords.length - 1"
        @click="chooseCut(wordIndex)"
      >
        {{ word }}
      </button>
    </div>

    <div class="stanza-editor-tools">
      <button type="button" :disabled="!canJoin" :class="{ active: joinedWithNext }" :aria-pressed="joinedWithNext" @click="join">
        <component :is="joinedWithNext ? Ungroup : Group" :size="20" /><span>{{ joinedWithNext ? 'Desunir' : 'Unir' }}</span>
      </button>
      <button type="button" :disabled="!canJoin" @click="joinText"><Merge :size="20" /><span>Juntar</span></button>
      <button type="button" :disabled="!canCut" @click="split"><Scissors :size="20" /><span>Separar</span></button>
      <button type="button" :disabled="selected === 0" :class="{ active: flat[selected]?.newPass }" @click="passRestart">
        <SeparatorHorizontal :size="20" /><span>Salto</span>
      </button>
      <button
        type="button"
        :disabled="!canCut"
        :class="{ active: canCut && selectedSplit === cut }"
        @click="voiceSplit"
      >
        <Slash :size="20" /><span>Rayita</span>
      </button>
      <button type="button" :class="{ active: isLineTogether(flat[selected]?.text ?? '') }" @click="together">
        <Link2 :size="20" /><span>Unión</span>
      </button>
    </div>
    <p class="stanza-editor-hint">Unir: esta línea y la de abajo, con la misma voz. Juntar: las dos en una sola línea.</p>

    <div class="stanza-editor-foot">
      <button type="button" :disabled="!history.length" @click="undo"><Undo2 :size="16" /> Deshacer</button>
      <button type="button" :disabled="!isEdited" @click="reset"><RotateCcw :size="16" /> Restablecer estrofa</button>
      <button type="button" @click="copyForTable"><Copy :size="16" /> {{ copied ? 'Copiado' : 'Copiar' }}</button>
    </div>
  </div>
</template>

<style scoped>
.stanza-editor {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 1300; /* por encima del botón flotante de grabar (1200), que tapaba «Copiar» */
  max-height: 62vh;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 12px 12px calc(12px + env(safe-area-inset-bottom, 0px));
  background: var(--surface);
  color: var(--ink);
  border-top: 2px solid var(--accent);
  border-radius: 16px 16px 0 0;
  box-shadow: var(--shadow);
  font-family: system-ui, sans-serif;
  font-size: 15px;
}

.stanza-editor button {
  font: inherit;
  color: inherit;
  background: var(--surface-muted);
  border: 1px solid var(--line);
  border-radius: 10px;
  cursor: pointer;
}

.stanza-editor button:disabled {
  opacity: 0.35;
}

.stanza-editor-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.stanza-editor-title {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}

.stanza-editor-status {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  color: var(--muted, var(--ink));
  opacity: 0.85;
}

.stanza-editor-status.is-sin-conexion {
  color: var(--rubric);
}

/* «Guardar»: el botón principal de la hoja, relleno y bien visible (Lucas, 14/11/2026). */
.stanza-editor .stanza-editor-done {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 44px;
  padding: 0 18px;
  font-weight: 700;
  background: var(--accent);
  border-color: var(--accent);
  color: var(--accent-ink) !important;
}

.stanza-editor-lines {
  list-style: none;
  margin: 0;
  padding: 0;
  overflow-y: auto;
  min-height: 0;
  flex: 1 1 auto;
}

.stanza-editor-lines li {
  display: flex;
  gap: 8px;
  align-items: stretch;
  margin-top: 4px;
}

.stanza-editor-lines li.has-pass-restart {
  margin-top: 12px;
  padding-top: 8px;
  border-top: 2px dashed var(--rubric);
}

.stanza-editor-label {
  flex: 0 0 40px;
  min-height: 40px;
  font-weight: 700;
  color: var(--rubric) !important;
}

.stanza-editor-text {
  flex: 1 1 auto;
  text-align: left;
  padding: 8px 10px;
  line-height: 1.3;
}

.stanza-editor-lines li.is-together .stanza-editor-text {
  border-left: 3px solid var(--rubric);
}

/* Versículos unidos (misma voz): la rayita verde de la izquierda, como en el texto. */
.stanza-editor-lines li.is-merged {
  position: relative;
}

.stanza-editor-lines li.is-merged::before {
  content: '';
  position: absolute;
  left: 44px;
  top: -4px;
  bottom: 0;
  width: 3px;
  background: var(--notation-color, var(--rubric));
}

.stanza-editor-lines li.is-merged:not(.is-continued)::before {
  top: 0;
}

.stanza-editor-lines li.is-merged .stanza-editor-text {
  margin-left: 6px;
}

.stanza-editor-lines li.is-selected .stanza-editor-text {
  border-color: var(--accent);
  box-shadow: inset 0 0 0 1px var(--accent);
}

.stanza-editor-words {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.stanza-editor-word {
  position: relative;
  min-height: 38px;
  padding: 0 10px;
}

.stanza-editor-word:disabled {
  opacity: 0.6 !important;
}

.stanza-editor-word.is-cut {
  border-color: var(--accent);
  border-right: 4px solid var(--accent);
}

.stanza-editor-word.has-split::after {
  content: '|';
  position: absolute;
  right: -6px;
  top: 6px;
  color: var(--rubric);
  font-weight: 700;
}

.stanza-editor-tools {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 6px;
}

.stanza-editor-tools button {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  min-height: 56px;
  padding: 0 2px;
  font-size: 12px;
  min-width: 0;
}

.stanza-editor-hint {
  margin: -4px 0 0;
  font-size: 12px;
  opacity: 0.7;
}

.stanza-editor-tools button.active {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 25%, var(--surface-muted));
}

.stanza-editor-foot {
  display: flex;
  gap: 8px;
}

.stanza-editor-foot button {
  flex: 1 1 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  min-height: 40px;
  font-size: 13px;
}
</style>
