import { shallowReactive } from 'vue'

// Capitulares ornamentadas de los días de solemnidad (estilo "vid": letra de pluma ancha con
// sarmientos blancos y la vid del color del día; Lucas eligió la A el 31/10/2026). Los SVG los
// genera scripts/capitulares/generar.mjs y usan solo currentColor, var(--accent) y var(--surface),
// así que siguen el color litúrgico y el tema sin tocarlos.
//
// Van en línea (no <img>) para heredar esos colores. Cada letra pesa ~100 KB sin comprimir
// (3-4 KB en gzip) y es un trozo aparte que se carga al hacer falta: solo las 4-6 letras del día.

/** Secciones de Laudes que abren con capitular: los puntos de los bocetos (Himno, salmodia,
 * Lectura breve y Benedictus). */
export const CAPITULAR_SECTION_TITLES = new Set([
  'Himno',
  'Primer salmo',
  'Segundo salmo',
  'Tercer salmo',
  'Lectura breve',
  'Cántico de Zacarías',
])

const SIGNOS: Record<string, string> = {
  Á: 'A-agudo',
  É: 'E-agudo',
  Í: 'I-agudo',
  Ó: 'O-agudo',
  Ú: 'U-agudo',
  Ñ: 'N-tilde',
  Ü: 'U-dieresis',
}

/** Nombre del SVG para una letra (null si no hay capitular para ella: dígitos, signos...). */
export function capitularFileName(letter: string): string | null {
  const upper = letter.toLocaleUpperCase('es')
  if (SIGNOS[upper]) {
    return SIGNOS[upper]
  }
  return /^[A-Z]$/.test(upper) ? upper : null
}

const loaders = import.meta.glob('../assets/capitulares/*.svg', { query: '?raw', import: 'default' }) as Record<
  string,
  () => Promise<string>
>
const loaded = shallowReactive(new Map<string, string>())
const pending = new Set<string>()

/** El SVG de la capitular si ya está cargado; si no, lo pide y devuelve undefined (quien lo lea
 * desde un computed se recalcula solo al llegar). */
export function capitularSvg(letter: string): string | undefined {
  const name = capitularFileName(letter)
  if (!name) {
    return undefined
  }
  const svg = loaded.get(name)
  if (svg !== undefined || pending.has(name)) {
    return svg
  }
  const loader = loaders[`../assets/capitulares/${name}.svg`]
  if (!loader) {
    return undefined
  }
  pending.add(name)
  loader()
    .then((text) => loaded.set(name, text))
    .catch(() => {
      // Sin la letra (trozo que no cargó) el texto sale con su mayúscula normal: no se reintenta.
    })
  return undefined
}

const SKIP_SELECTOR = '.antiphon-line, .rubric, .notation-label, .responsory-split-mark'

function firstTextNode(line: Element): Text | null {
  const walker = document.createTreeWalker(line, NodeFilter.SHOW_TEXT)
  for (let node = walker.nextNode(); node; node = walker.nextNode()) {
    if (node.parentElement?.closest(SKIP_SELECTOR)) {
      continue
    }
    if (node.textContent?.trim()) {
      return node as Text
    }
  }
  return null
}

/**
 * Pone la capitular en la primera letra del texto de la sección (HTML ya montado por
 * renderPrayerText). La letra original sigue en el texto, oculta a la vista pero no al lector de
 * pantalla ni al copiar; el dibujo es decorativo (aria-hidden).
 *
 * Dónde flota: en una estrofa con notación de canto cada grupo de versos es una rejilla, y un
 * float dentro de una línea quedaría encerrado en su grupo (lo estiraría a la altura de la letra).
 * Por eso ahí va al principio del primer trozo de notación: los grupos que tiene al lado se
 * estrechan y los de debajo vuelven al ancho completo, sin sangrar la estrofa entera. En el texto
 * normal (Lectura breve) va dentro de la propia línea y el párrafo lo rodea.
 *
 * Si el texto empieza por algo que no es letra (¡, ¿, comillas...), no hay capitular.
 */
export function applyCapitular(html: string): string {
  if (!html || typeof document === 'undefined') {
    return html
  }
  const template = document.createElement('template')
  template.innerHTML = html

  const line = Array.from(template.content.querySelectorAll('.source-line')).find(
    (candidate) => !candidate.closest('.is-centered-instruction') && firstTextNode(candidate),
  )
  const text = line ? firstTextNode(line) : null
  if (!line || !text) {
    return html
  }

  const raw = text.textContent ?? ''
  const start = raw.search(/\S/)
  const letter = raw[start]
  const svg = letter && /\p{L}/u.test(letter) ? capitularSvg(letter) : undefined
  if (!svg) {
    return html
  }

  const rest = text.splitText(start)
  rest.textContent = (rest.textContent ?? '').slice(letter.length)
  const hidden = document.createElement('span')
  hidden.className = 'capitular-letra'
  hidden.textContent = letter
  rest.before(hidden)

  const drop = document.createElement('span')
  drop.className = 'capitular'
  drop.setAttribute('aria-hidden', 'true')
  drop.innerHTML = svg
  const chunk = line.closest('.notation-chunk')
  if (chunk) {
    chunk.prepend(drop)
  } else {
    line.prepend(drop)
  }
  line.closest('.source-stanza')?.classList.add('has-capitular')

  return template.innerHTML
}
