/** `fecha` en YYYY-MM-DD; `celebracion`, el nombre litúrgico del día (o de la opción elegida). */
export function grabadoDelDia(fecha: string, celebracion: string | undefined): GrabadoSanto | null {
  const dia = fecha.slice(5, 10)
  const nombre = (celebracion ?? '').normalize('NFC')
  return GRABADOS_SANTOS.find((g) => (g.dia ?? dia) === dia && nombre.includes(g.clave)) ?? null
}
