<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import type { Component } from 'vue'
import {
  ChevronsDown,
  ChevronsUp,
  Flame,
  Landmark,
  MessageSquare,
  Mic2,
  MoonStar,
  Play,
  RotateCcw,
  Scroll,
  Snowflake,
  Square,
  Swords,
  TrendingDown,
  TrendingUp,
  TreeDeciduous,
  Unlink,
  Users,
} from '@lucide/vue'
import type { PrayerSection } from '../lib/prayer'
import { LAUDES_CHANT_DEFAULTS, LAUDES_CHANT_POOLS, type ChantVariant } from '../lib/chant-catalog'
import { renderChordSheet } from '../lib/chord-sheet'
import { buildChantCycleOrder, computeStanzaLineCountEntries, preferredChantFamily } from '../lib/chant-cycle'
import { renderPrayerText, type SingingNotationMode } from '../lib/text'
import { applyCapitular, CAPITULAR_SECTION_TITLES } from '../lib/capitulares'
import { ORNAMENTO_VINETA } from '../lib/ornamentos'
import { stanzaEditMode, stanzaEdits } from '../lib/stanza-edit-store'
import StanzaEditor, { type EditableStanza } from './StanzaEditor.vue'
import type { EditableMode } from '../lib/stanza-edit'

// Iconos de las melodías de Laudes (chant-catalog.ts referencia cada uno por nombre).
const CHANT_ICONS: Record<string, Component> = {
  ChevronsDown,
  ChevronsUp,
  Flame,
  Landmark,
  MessageSquare,
  Mic2,
  MoonStar,
  Scroll,
  Snowflake,
  Swords,
  TrendingDown,
  TrendingUp,
  TreeDeciduous,
  Unlink,
  Users,
}

const props = defineProps<{
  section: PrayerSection
  alternativeIndex?: number
  notationEnabled?: boolean
  notationMode: SingingNotationMode
  /** Solo en Laudes: activa el ChantPicker (icono de cántico + capo) en vez del modo de voces manual. */
  chantPickerEnabled?: boolean
  /** Muestra el texto de las indicaciones posturales (Nos ponemos en pie, Nos sentamos...).
   * Desactivado, solo queda el símbolo † de la señal de la cruz. */
  postureInstructionsEnabled?: boolean
  /** Desplazamiento de capo de esta sección, controlado por App.vue (que es quien lo
   * propaga a las secciones posteriores al ciclar el numerito, y quien lo restaura de la nube). */
  capoOffset?: number
  /** Desplazamiento que esta sección heredó de la anterior al propagarse (0 si nada). Fija el
   * orden del ciclo del numerito: de lo heredado se pasa primero a 0, luego a lo demás. */
  inheritedCapoOffset?: number
  /** Cántico guardado para esta sección (nube `canticos.json` del día, gobernada por App.vue).
   * Si está, manda sobre el `localStorage` del último rezo y sobre la heurística de familia
   * preferida — es la selección real de ese día concreto. */
  chantKey?: string
  /** Cántico con el que se rezó antes este salmo (memoria por salmo): lleva el puntito. */
  historicChantKey?: string
  /** Claves de cántico ya elegidas por las secciones anteriores de la misma Hora (recorriendo
   * por índice, igual que `inheritedCapoOffset`). Quedan fuera del ciclo de esta sección para
   * no repetir melodía dentro del mismo día (Lucas, 05/09/2026). */
  takenChantKeys?: string[]
  /** Día de solemnidad en Laudes con el ajuste de iniciales encendido: el texto de las secciones
   * principales abre con capitular ornamentada (ver lib/capitulares.ts). */
  capitularEnabled?: boolean
  /** Día de solemnidad con el ajuste de ornamentos encendido: viñeta de vid delante del título. */
  ornamented?: boolean
}>()

const emit = defineEmits<{
  (event: 'update:alternativeIndex', value: number): void
  (event: 'update:notationMode', value: SingingNotationMode): void
  /** Cántico+capo elegidos en esta sección (solo cuando el ChantPicker está activo) —
   * lo consume App.vue para poder generar la descripción del vídeo al terminar el rezo. */
  (event: 'chant-selected', value: { key: string; capoOffset: number }): void
  /** Lucas ha cambiado el cántico a mano (ciclando el icono). */
  (event: 'chant-cycled', key: string): void
  /** Lucas tocó el numerito de capo: el nuevo desplazamiento de esta sección. App.vue pone
   * ese mismo desplazamiento (absoluto, no acumulativo) a todas las secciones posteriores
   * (pedido 01/09/2026). */
  (event: 'capo-cycled', offset: number): void
}>()

const notationSectionTitles = new Set([
  'Himno',
  'Primer salmo',
  'Segundo salmo',
  'Tercer salmo',
  'Cántico de Zacarías',
  'Cántico de María',
  'Cántico evangélico',
])

// Secciones cantadas donde tiene sentido contar los versos de cada estrofa. Es un
// superconjunto de las que llevan notación de canto: el Salmo invitatorio se canta igual,
// pero no pasa por el motor de notación, y aun así el numerito ayuda a elegir melodía
// (05/09/2026, Lucas: el indicador debe salir en todas las Horas, no solo en Laudes).
const verseCountSectionTitles = new Set([...notationSectionTitles, 'Salmo invitatorio'])

const notationApplies = computed(() => notationSectionTitles.has(props.section.title))
const verseCountApplies = computed(() => verseCountSectionTitles.has(props.section.title))
const localAlternativeIndex = ref(0)

// El cántico de 'Oh Cruz Fiel' solo se ofrece cuando el himno del día es ese (Lucas, 25/10/2026): no
// entra en el ciclo de los himnos genéricos.
const chantPool = computed<ChantVariant[] | undefined>(() => {
  const pool = props.chantPickerEnabled ? LAUDES_CHANT_POOLS[props.section.title] : undefined
  if (props.section.title !== 'Himno' || !pool) {
    return pool
  }

  return activeBodyContent.value.trimStart().startsWith('¡Oh cruz fiel') ? pool : pool.filter((chant) => chant.key !== 'cruz-fiel')
})
const selectedChantKey = ref('')
// Punto de arranque del orden de ciclo (B, 05/09/2026): se fija cuando se resuelve la
// selección de la sección (al montar / cambiar de contenido, o al llegar tarde el cántico de
// la nube) y NO se mueve en cada click -- si effectiveChantPool reordenara con la
// selección más reciente como "actual" en cada click, el ciclo oscilaría entre dos melodías
// en vez de recorrer toda la familia (bug real, visto con Playwright antes de fijar esto).
const chantCycleAnchorKey = ref('')
const capoOffset = ref<number>(props.capoOffset ?? 0)

watch(
  () => props.capoOffset,
  (value) => {
    if (value !== undefined && value !== capoOffset.value) {
      capoOffset.value = value
    }
  },
)

// El cántico de la nube (canticos.json) puede llegar después de resolverse la selección
// inicial (fetch asíncrono en App.vue) -- si llega y manda, se adopta igual que capoOffset.
watch(
  () => props.chantKey,
  (value) => {
    if (value && value !== selectedChantKey.value && chantPool.value?.some((chant) => chant.key === value)) {
      selectedChantKey.value = value
      chantCycleAnchorKey.value = value
    }
  },
)

// Recuerda, por título de sección, el último cántico elegido al rezar — así el
// ChantPicker arranca en lo que se cantó la última vez, no siempre en el mismo default.
const CHANT_SELECTION_STORAGE_KEY = 'orante:chant-selection'

function readChantSelections(): Record<string, string> {
  try {
    const raw = localStorage.getItem(CHANT_SELECTION_STORAGE_KEY)
    return raw ? JSON.parse(raw) : {}
  } catch {
    return {}
  }
}

function writeChantSelection(sectionTitle: string, key: string): void {
  try {
    const current = readChantSelections()
    localStorage.setItem(CHANT_SELECTION_STORAGE_KEY, JSON.stringify({ ...current, [sectionTitle]: key }))
  } catch {
    // localStorage no disponible (modo privado, cuota llena...): se pierde la persistencia
    // entre días, pero no rompe el ChantPicker de esta sesión.
  }
}

// Puntito (04/11/2026, Lucas): el cántico que suena es el que él guardó (a mano para este día, o
// el de la última vez con este salmo) y no uno puesto por defecto. App.vue decide cuál es
// (historicChantKey, desde canticos.json); antes iba en localStorage por título de sección, sin
// fecha y por dispositivo, y no casaba con lo guardado en la nube.
const isChantManual = computed(
  () => Boolean(selectedChantKey.value) && props.historicChantKey === selectedChantKey.value,
)

// Claves ya tomadas por secciones anteriores de la misma Hora (App.vue las calcula
// recorriendo por índice, igual que inheritedCapoOffset) -- nunca repetir melodía entre
// secciones dentro del mismo día (Lucas, 05/09/2026).
const takenChantKeys = computed<string[]>(() => props.takenChantKeys ?? [])

function defaultChantKeyForCurrentSection(): string {
  const pool = chantPool.value
  if (!pool?.length) {
    return ''
  }

  // Lo guardado para hoy (nube canticos.json, gobernado por App.vue) manda sobre todo lo demás.
  if (props.chantKey && pool.some((chant) => chant.key === props.chantKey)) {
    return props.chantKey
  }

  const lastUsedKey = readChantSelections()[props.section.title]
  if (lastUsedKey && pool.some((chant) => chant.key === lastUsedKey)) {
    return lastUsedKey
  }

  // Sin nada guardado: arranca por la familia preferida según el recuento de versos (05/09/2026),
  // en la primera melodía disponible de esa familia que no esté ya tomada más arriba.
  const preferred = preferredChantFamily(stanzaLineCountEntries.value)
  if (preferred !== undefined) {
    const preferredOrder = buildChantCycleOrder(pool, { preferredFamily: preferred, takenKeys: takenChantKeys.value })
    if (preferredOrder[0]) {
      return preferredOrder[0].key
    }
  }

  return LAUDES_CHANT_DEFAULTS[props.section.title] ?? pool[0].key
}

const selectedChant = computed<ChantVariant | undefined>(() =>
  chantPool.value?.find((chant) => chant.key === selectedChantKey.value) ?? chantPool.value?.[0],
)
const displayedCapo = computed(() => Math.max(0, (selectedChant.value?.capo ?? 0) + capoOffset.value))
const chantIcon = computed<Component | undefined>(() =>
  selectedChant.value ? CHANT_ICONS[selectedChant.value.icon] : undefined,
)

// Orden de ciclo del ChantPicker (05/09/2026, sustituye al reordenado-sin-excluir anterior):
// la actual va primera, luego el resto de su misma familia (mismas voces) en orden de
// catálogo, luego la otra familia -- y se excluyen las claves ya tomadas por secciones
// anteriores (con blindaje: si la exclusión vaciara el pool, no se excluye nada). Ver
// chant-cycle.ts y su test para el detalle y los casos límite.
const effectiveChantPool = computed<ChantVariant[] | undefined>(() => {
  const pool = chantPool.value
  if (!pool?.length) {
    return pool
  }

  return buildChantCycleOrder(pool, {
    currentKey: chantCycleAnchorKey.value || undefined,
    preferredFamily: preferredChantFamily(stanzaLineCountEntries.value),
    takenKeys: takenChantKeys.value,
  })
})

function cycleChant(): void {
  const pool = effectiveChantPool.value
  if (!pool || pool.length < 2) {
    return
  }

  const currentIndex = pool.findIndex((chant) => chant.key === selectedChantKey.value)
  selectedChantKey.value = pool[(currentIndex + 1) % pool.length].key
  emit('chant-cycled', selectedChantKey.value)
  // El desplazamiento de capo se conserva al cambiar de melodía: es la transposición de la
  // voz de hoy (y se ha propagado a las secciones siguientes), no un ajuste de esa melodía.
}

/** Orden del ciclo del numerito, por probabilidad de lo que Lucas necesita (01/09/2026):
 * - sin herencia (0): 0 → -1 (voz grave recién levantado, lo más habitual) → +1 → 0;
 * - heredó -1 de una sección anterior: -1 → 0 (recuperar) → +1 → -1 (deshacer, vuelve a lo heredado);
 * - heredó +1: +1 → 0 → -1 → +1.
 * Es decir: se arranca en lo heredado, sigue 0, y el resto con "bajar" antes que "subir". */
function capoCycleOrder(inherited: number): number[] {
  const order = [inherited, 0, -1, 1]
  return order.filter((value, index) => order.indexOf(value) === index)
}

function nextCapoOffset(offset: number, inherited: number): number {
  const order = capoCycleOrder(inherited)
  const index = order.indexOf(offset)
  return index === -1 ? inherited : order[(index + 1) % order.length]
}

function cycleCapo(): void {
  const next = nextCapoOffset(capoOffset.value, props.inheritedCapoOffset ?? 0)
  capoOffset.value = next
  emit('capo-cycled', next)
}

const isAnnouncementsSection = computed(() => props.section.kind === 'mass' && props.section.title === 'Avisos')
const ANNOUNCEMENTS_HISTORY_KEY = 'orante:announcements-timer-history'
const ANNOUNCEMENTS_HISTORY_LIMIT = 8

interface AnnouncementsTimerEntry {
  durationMs: number
  stoppedAt: string
}

interface SectionAlternative {
  label: string
  eyebrow?: string
  content: string
}

function alternativeLabel(index: number): string {
  return props.section.title === 'Himno' ? `Himno ${index + 1}` : `Opción ${index + 1}`
}

function splitAlternatives(content?: string): SectionAlternative[] {
  const text = content?.trim()

  if (!text) {
    return []
  }

  const parts = text
    .replace(/\r\n/g, '\n')
    .split(/(?:^|\n)\s*\$?\s*O\s+bien\s*:?\s*\$?\s*/gim)
    .map((part) => part.trim())
    .filter(Boolean)

  return (parts.length ? parts : [text]).map((part, index) => ({
    label: alternativeLabel(index),
    content: part,
  }))
}

const contentAlternatives = computed(() =>
  props.section.alternatives?.length ? props.section.alternatives : splitAlternatives(props.section.content),
)
const showAlternativeTabs = computed(() => contentAlternatives.value.length > 1)
const activeAlternativeIndex = computed(() => {
  const requestedIndex = props.alternativeIndex ?? localAlternativeIndex.value
  return requestedIndex >= 0 && requestedIndex < contentAlternatives.value.length ? requestedIndex : 0
})
const sectionRubrics = computed(() => props.section.rubrics?.filter((rubric) => rubric.trim()).join('\n\n') ?? '')
const activeBodyContent = computed(() => contentAlternatives.value[activeAlternativeIndex.value]?.content ?? '')
const activeEyebrow = computed(() => contentAlternatives.value[activeAlternativeIndex.value]?.eyebrow ?? props.section.eyebrow)

// Para cada estrofa (separada por línea en blanco) cuenta sus versos, ignorando el Gloria al
// Padre y las líneas de antífona repetida (lógica pura en chant-cycle.ts, testeada aparte).
// `entries` guarda cada número de versos distinto junto a cuántas veces aparece una estrofa
// con esa cantidad, ordenado por apariciones (de más a menos) y, en empate, por número de
// versos (de menor a mayor). Declarado antes del watch de más abajo que arranca la selección
// de cántico (defaultChantKeyForCurrentSection la usa para la heurística de familia).
const stanzaLineCountEntries = computed(() => {
  if (!verseCountApplies.value || !activeBodyContent.value.trim()) {
    return []
  }

  return computeStanzaLineCountEntries(activeBodyContent.value)
})

const stanzaLineCountsArray = computed(() => stanzaLineCountEntries.value.map((entry) => entry.lineCount))

const announcementsElapsedMs = ref(0)
const announcementsRunning = ref(false)
const announcementsHistory = ref<AnnouncementsTimerEntry[]>(readAnnouncementsHistory())
const showAnnouncementsHistory = ref(false)
let announcementsTimerBaseMs = 0
let announcementsTimerStartedAt = 0
let announcementsTimerId: number | undefined

watch(
  () => props.section.content,
  () => {
    localAlternativeIndex.value = 0
    selectedChantKey.value = defaultChantKeyForCurrentSection()
    chantCycleAnchorKey.value = selectedChantKey.value
    // El capo no se resetea aquí: lo gobierna App.vue (lo vacía al cambiar de fecha).
  },
  { immediate: true },
)

// Si la selección actual de esta sección resulta tomada por una sección anterior (p. ej.
// Lucas cicló el primer salmo hasta caer en la melodía que ya tenía el segundo, o llegó una
// selección de la nube que choca con otra sección), esta sección se desplaza sola a la
// primera melodía disponible del orden de ciclo -- nunca queda una melodía repetida a la vista.
watch(
  effectiveChantPool,
  (pool) => {
    if (!pool?.length || !selectedChantKey.value) {
      return
    }

    if (takenChantKeys.value.includes(selectedChantKey.value) && pool[0].key !== selectedChantKey.value) {
      selectedChantKey.value = pool[0].key
    }
  },
  { immediate: true },
)

watch(contentAlternatives, (alternatives) => {
  if (localAlternativeIndex.value >= alternatives.length) {
    localAlternativeIndex.value = 0
  }
})

// Notifica al padre cada vez que cambia la selección (por defecto al entrar, o al ciclar
// icono/capo) para que pueda recolectarla al terminar el rezo, y además persiste el
// cántico (no el capo, que es relativo a la sesión) para que sea el default del próximo día.
watch(
  [selectedChantKey, capoOffset],
  ([key, offset]) => {
    if (chantPool.value?.length) {
      emit('chant-selected', { key, capoOffset: offset })
      writeChantSelection(props.section.title, key)
    }
  },
  { immediate: true },
)

onBeforeUnmount(() => {
  clearAnnouncementsTimer()
})

function setAlternativeIndex(index: number): void {
  localAlternativeIndex.value = index
  emit('update:alternativeIndex', index)
}

function readAnnouncementsHistory(): AnnouncementsTimerEntry[] {
  try {
    const parsed = JSON.parse(localStorage.getItem(ANNOUNCEMENTS_HISTORY_KEY) ?? '[]')

    return Array.isArray(parsed)
      ? parsed
          .filter((entry) => Number.isFinite(entry?.durationMs) && typeof entry?.stoppedAt === 'string')
          .slice(0, ANNOUNCEMENTS_HISTORY_LIMIT)
      : []
  } catch {
    return []
  }
}

function saveAnnouncementsHistory(entries: AnnouncementsTimerEntry[]): void {
  localStorage.setItem(ANNOUNCEMENTS_HISTORY_KEY, JSON.stringify(entries.slice(0, ANNOUNCEMENTS_HISTORY_LIMIT)))
}

function clearAnnouncementsTimer(): void {
  if (announcementsTimerId !== undefined) {
    window.clearInterval(announcementsTimerId)
    announcementsTimerId = undefined
  }
}

function updateAnnouncementsElapsed(): void {
  if (!announcementsRunning.value) {
    return
  }

  announcementsElapsedMs.value = announcementsTimerBaseMs + Date.now() - announcementsTimerStartedAt
}

function startAnnouncementsTimer(): void {
  if (announcementsRunning.value) {
    return
  }

  showAnnouncementsHistory.value = false
  announcementsTimerBaseMs = announcementsElapsedMs.value
  announcementsTimerStartedAt = Date.now()
  announcementsRunning.value = true
  clearAnnouncementsTimer()
  announcementsTimerId = window.setInterval(updateAnnouncementsElapsed, 250)
}

function stopAnnouncementsTimer(): void {
  if (!announcementsRunning.value) {
    return
  }

  updateAnnouncementsElapsed()
  announcementsRunning.value = false
  clearAnnouncementsTimer()

  const durationMs = Math.round(announcementsElapsedMs.value / 1000) * 1000
  if (durationMs > 0) {
    announcementsHistory.value = [
      { durationMs, stoppedAt: new Date().toISOString() },
      ...announcementsHistory.value,
    ].slice(0, ANNOUNCEMENTS_HISTORY_LIMIT)
    saveAnnouncementsHistory(announcementsHistory.value)
  }
  showAnnouncementsHistory.value = true
}

function resetAnnouncementsTimer(): void {
  announcementsRunning.value = false
  clearAnnouncementsTimer()
  announcementsElapsedMs.value = 0
}

function formatDuration(value: number): string {
  const totalSeconds = Math.max(0, Math.round(value / 1000))
  const seconds = totalSeconds % 60
  const minutes = Math.floor(totalSeconds / 60) % 60
  const hours = Math.floor(totalSeconds / 3600)
  const paddedSeconds = String(seconds).padStart(2, '0')
  const paddedMinutes = hours ? String(minutes).padStart(2, '0') : String(minutes)

  return hours ? `${hours}:${paddedMinutes}:${paddedSeconds}` : `${paddedMinutes}:${paddedSeconds}`
}

function formatHistoryTime(value: string): string {
  const date = new Date(value)

  if (Number.isNaN(date.getTime())) {
    return ''
  }

  return new Intl.DateTimeFormat('es', {
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    month: 'short',
  }).format(date)
}

const announcementsTimerDisplay = computed(() => formatDuration(announcementsElapsedMs.value))
const recentAnnouncementsHistory = computed(() => announcementsHistory.value.slice(0, 5))
const announcementsHistoryAverage = computed(() => {
  if (!announcementsHistory.value.length) {
    return ''
  }

  const average =
    announcementsHistory.value.reduce((total, entry) => total + entry.durationMs, 0) / announcementsHistory.value.length

  return formatDuration(average)
})

// Versión compacta que se muestra junto al título: "23, 34" = 3 estrofas de 2 versos
// y 4 estrofas de 3 versos (primero el número de versos, después cuántas veces aparece).
// En Laudes va pegada al ChantPicker; en el resto de Horas (Invitatorio, Oficio, Tercia,
// Sexta, Nona, Vísperas, Completas) va sola en el mismo sitio.
const stanzaLineCountsCompact = computed(() =>
  stanzaLineCountEntries.value.map((entry) => `${entry.lineCount}${entry.occurrences}`).join(', '),
)

const notationModes = computed<SingingNotationMode[]>(() => {
  // Cántico de Zacarías: melodía fija (capo 2, 4 voces) — sin selector manual.
  if (props.section.title === 'Cántico de Zacarías') {
    return [4]
  }

  return props.section.title === 'Himno' ? [3, 4] : [2, 4]
})

const effectiveNotationMode = computed<SingingNotationMode>(() =>
  notationModes.value.includes(props.notationMode) ? props.notationMode : notationModes.value[0],
)

function setNotationMode(mode: SingingNotationMode): void {
  emit('update:notationMode', mode)
}

// Secciones donde el ChantPicker (icono de cántico) decide el modo de voces en vez del
// selector manual — el resto de secciones con notación (Cántico de María, Cántico
// evangélico en Completorio) siguen con el comportamiento de siempre.
const CHANT_VOICE_SECTIONS = new Set(['Himno', 'Primer salmo', 'Segundo salmo', 'Tercer salmo', 'Cántico de Zacarías'])
const effectiveVoiceMode = computed<SingingNotationMode>(() =>
  chantPool.value && CHANT_VOICE_SECTIONS.has(props.section.title) && selectedChant.value?.voices
    ? selectedChant.value.voices
    : effectiveNotationMode.value,
)

const hasRenderableSectionContent = computed(
  () => Boolean(activeBodyContent.value.trim()) || Boolean(props.section.items?.length),
)
const showChantPicker = computed(() => Boolean(chantPool.value?.length) && hasRenderableSectionContent.value)

const showNotationControls = computed(
  () =>
    !showChantPicker.value &&
    props.notationMode &&
    notationApplies.value &&
    stanzaLineCountsCompact.value !== '' &&
    notationModes.value.length > 1 &&
    (Boolean(activeEyebrow.value) || props.section.title === 'Himno'),
)
// El picker siempre va junto al título, en su misma fila (con fallback a línea propia
// si el título no le deja hueco) — el eyebrow (cuando lo hay) queda en su propia fila
// debajo, sin compartirla con el picker.
const showTopChantPicker = computed(() => showChantPicker.value)
// El contador de versos vive en esa misma fila del título en TODAS las Horas, haya o no
// ChantPicker (que solo existe en Laudes).
const showTopVerseCounts = computed(
  () => stanzaLineCountsCompact.value !== '' && hasRenderableSectionContent.value,
)
const showTopRow = computed(() => showTopChantPicker.value || showTopVerseCounts.value)
const showEyebrowRow = computed(() => Boolean(activeEyebrow.value) || showNotationControls.value)
// Excepcional (Lucas, 13/09/2026): algún himno propio de letra fija (p. ej. 'cruz-fiel', ver
// chant-catalog.ts) trae su propia cifra completa -- se muestra intercalada sobre el texto en
// vez del cuerpo normal de la Hora, igual que la cifra de un canto de Misa (chord-sheet.ts).
// Solo en modo coro (props.notationEnabled, el mismo toggle "Modo coro" de siempre): fuera de
// ese modo se ve el texto normal de la Hora, como cualquier otro día (Lucas, 13/09/2026).
const exceptionalChordSheet = computed(() =>
  props.section.title === 'Himno' && props.notationEnabled ? selectedChant.value?.chordSheet : undefined,
)

// "Oh Cruz Fiel" tiene su propia melodía compuesta a medida de sus estrofas (no una de las
// genéricas del picker) -- si se elige igualmente 'greg'/'desc' para ver otra cosa, la notación
// de esas melodías no debe intentar repartir sus líneas en grupos de 3/4 fusionando versos con
// una rayita: no hay nada que unir, cada estrofa ya está pensada para su propia música (Lucas,
// 13/09/2026). Se detecta por el texto (no por el cántico elegido) para que aplique da igual cuál
// esté seleccionado en el picker.
const isFixedProperHymn = computed(
  () => props.section.title === 'Himno' && activeBodyContent.value.trimStart().startsWith('¡Oh cruz fiel'),
)

// Capitular ornamentada en las solemnidades (App.vue decide si toca: ajuste, Hora y rango del día).
function withCapitular(html: string): string {
  return props.capitularEnabled && CAPITULAR_SECTION_TITLES.has(props.section.title) ? applyCapitular(html) : html
}

const renderedActiveContent = computed(() =>
  [
    sectionRubrics.value
      ? renderPrayerText(sectionRubrics.value, { postureInstructionsEnabled: props.postureInstructionsEnabled })
      : '',
    exceptionalChordSheet.value
      ? renderChordSheet(exceptionalChordSheet.value)
      : activeBodyContent.value
        ? withCapitular(renderPrayerText(activeBodyContent.value, {
            singingNotationMode: !notationApplies.value || isFixedProperHymn.value ? undefined : effectiveVoiceMode.value,
            minimalSingingNotation: props.notationEnabled === false,
            postureInstructionsEnabled: props.postureInstructionsEnabled,
            // Solo el Himno reparte una estrofa larga en dos pasadas de la melodía, con marca de
            // reinicio en medio (Lucas, 06/09/2026). En salmos y cánticos una estrofa larga es lo
            // normal y no se señala nada.
            hymnNotation: props.section.title === 'Himno',
            // 'bus' de 'busque' solo se subraya con el cántico descendente de cuatro (Lucas, 25/10/2026).
            syllableMarks: props.section.title === 'Himno' && selectedChant.value?.key === 'desc',
            // Modo edición de estrofas (Lucas, 02/11/2026; salmos y cánticos desde el 09/11/2026): sus
            // repartos propios siempre, y con el lápiz encendido, estrofas tocables.
            stanzaEdits: stanzaEdits.value,
            stanzaEditMode: stanzaEditMode.value,
            stanzaEditScope: stanzaEditScope.value,
          }))
        : '',
  ]
    .filter(Boolean)
    .join(''),
)

// Qué texto es, para la clave del Gloria (ver `stanzaKey`): la cita del salmo o cántico, o el título.
const stanzaEditScope = computed(() => activeEyebrow.value?.trim() || props.section.title)

// Estrofa que Lucas está editando (modo edición de estrofas). Se lee de los data-* que deja text.ts.
const editingStanza = ref<EditableStanza | null>(null)
const prayerCopy = ref<HTMLElement | null>(null)

function onPrayerCopyClick(event: MouseEvent): void {
  if (!stanzaEditMode.value || !notationApplies.value) {
    return
  }
  const element = (event.target as HTMLElement | null)?.closest<HTMLElement>('.stanza-edit')
  if (!element?.dataset.stanzaKey || !element.dataset.stanzaLayout) {
    return
  }
  editingStanza.value = {
    key: element.dataset.stanzaKey,
    mode: Number(element.dataset.stanzaMode) as EditableMode,
    layout: JSON.parse(element.dataset.stanzaLayout),
    verses: JSON.parse(element.dataset.stanzaVerses ?? '[]'),
  }
  element.scrollIntoView({ block: 'start', behavior: 'smooth' })
}

// Al apagar el lápiz (o cambiar de modo de voces) se cierra la hoja.
watch([stanzaEditMode, effectiveVoiceMode], () => {
  editingStanza.value = null
})

// La estrofa abierta se resalta; el v-html la repinta en cada cambio, así que se reaplica.
watch(
  [renderedActiveContent, editingStanza],
  () => {
    const root = prayerCopy.value
    if (!root) {
      return
    }
    root.querySelectorAll<HTMLElement>('.stanza-edit').forEach((element) => {
      element.classList.toggle('is-editing', element.dataset.stanzaKey === editingStanza.value?.key)
    })
  },
  { flush: 'post' },
)
</script>

<template>
  <section
    class="prayer-section"
    :data-section-title="section.title"
    :class="{
      'is-quiet': section.quiet,
      'is-part': section.kind === 'part',
      'is-mass': section.kind === 'mass',
    }"
  >
    <div class="section-heading">
      <div class="section-heading-top" :class="{ 'has-chant-picker': showTopRow }">
        <h3><span v-if="ornamented" class="ornamento section-vineta" aria-hidden="true" v-html="ORNAMENTO_VINETA" />{{ section.title }}</h3>
        <div v-if="showTopRow" class="chant-picker">
          <span v-if="showTopVerseCounts" class="chant-picker-verse-counts"
            >{{ stanzaLineCountsCompact }}<template v-if="showTopChantPicker">,</template></span
          >
          <span v-if="showTopChantPicker" class="chant-picker-chant">
            <button
              type="button"
              class="chant-capo-badge"
              :aria-label="`Capo ${displayedCapo}`"
              @click="cycleCapo"
            >
              {{ displayedCapo }}
            </button>
            <span class="chant-picker-sep" aria-hidden="true">&nbsp;</span>
            <button
              type="button"
              class="chant-picker-bubble"
              :class="{ 'is-fixed': (effectiveChantPool?.length ?? 0) < 2 }"
              :aria-label="selectedChant ? `Cántico: ${selectedChant.label}` : 'Cántico'"
              @click="cycleChant"
            >
              <component :is="chantIcon" v-if="chantIcon" :size="13" />
              <!-- Subíndice con el nº de voces del cántico (2/3/4), para reconocerlo de un vistazo
                   sin memorizar el icono — pedido de Lucas 01/09/2026. Sin voces (Invocación,
                   Padre nuestro) no se muestra nada. -->
              <sub v-if="selectedChant?.voices" class="chant-voices-sub" aria-hidden="true">{{ selectedChant.voices }}</sub>
              <span v-if="isChantManual" class="chant-manual-dot" aria-hidden="true" title="Elegido por ti" />
            </button>
          </span>
        </div>
      </div>
      <div
        v-if="showEyebrowRow"
        class="section-eyebrow-row"
        :class="{ hymn: props.section.title === 'Himno' }"
      >
        <p v-if="activeEyebrow" class="section-eyebrow">{{ activeEyebrow }}</p>
        <div v-if="showNotationControls" class="section-line-counts-row">
          <div class="notation-mode-mini" role="group" aria-label="Modo de notacion">
            <button
              type="button"
              class="notation-mode-pill"
              v-for="mode in notationModes"
              :key="mode"
              :class="{ active: effectiveNotationMode === mode }"
              :aria-label="`Modo de ${mode} lineas`"
              @click="setNotationMode(mode)"
            >
              {{ mode }}
            </button>
          </div>
        </div>
      </div>
      <p v-if="section.summary" class="section-summary">{{ section.summary }}</p>
    </div>

    <div v-if="showAlternativeTabs" class="section-alternative-tabs" role="tablist" aria-label="Alternativas">
      <button
        v-for="(alternative, index) in contentAlternatives"
        :key="alternative.label"
        type="button"
        class="section-alternative-tab"
        :class="{ active: activeAlternativeIndex === index }"
        role="tab"
        :aria-selected="activeAlternativeIndex === index"
        @click="setAlternativeIndex(index)"
      >
        {{ alternative.label }}
      </button>
    </div>

    <div
      v-if="renderedActiveContent"
      ref="prayerCopy"
      class="prayer-copy"
      :class="{ 'is-stanza-editing': stanzaEditMode && notationApplies }"
      @click="onPrayerCopyClick"
      v-html="renderedActiveContent"
    />
    <Teleport v-if="editingStanza" to=".app">
      <StanzaEditor :key="editingStanza.key" :stanza="editingStanza" @close="editingStanza = null" />
    </Teleport>

    <div v-if="isAnnouncementsSection" class="announcements-timer">
      <div class="announcements-timer-main">
        <div class="announcements-time" :class="{ running: announcementsRunning }">
          {{ announcementsTimerDisplay }}
        </div>
        <div class="announcements-actions">
          <button
            v-if="!announcementsRunning"
            type="button"
            class="announcements-action primary"
            aria-label="Iniciar cronómetro"
            @click="startAnnouncementsTimer"
          >
            <Play :size="15" />
            <span>Iniciar</span>
          </button>
          <button
            v-else
            type="button"
            class="announcements-action primary"
            aria-label="Detener cronómetro"
            @click="stopAnnouncementsTimer"
          >
            <Square :size="14" />
            <span>Detener</span>
          </button>
          <button
            type="button"
            class="announcements-action subtle"
            aria-label="Reiniciar cronómetro"
            :disabled="announcementsElapsedMs === 0 && !announcementsRunning"
            @click="resetAnnouncementsTimer"
          >
            <RotateCcw :size="14" />
          </button>
        </div>
      </div>

      <div v-if="showAnnouncementsHistory && recentAnnouncementsHistory.length" class="announcements-history">
        <div class="announcements-history-summary">
          <span>Histórico</span>
          <strong>Media {{ announcementsHistoryAverage }}</strong>
        </div>
        <ol>
          <li v-for="entry in recentAnnouncementsHistory" :key="`${entry.stoppedAt}-${entry.durationMs}`">
            <span>{{ formatHistoryTime(entry.stoppedAt) }}</span>
            <strong>{{ formatDuration(entry.durationMs) }}</strong>
          </li>
        </ol>
      </div>
    </div>

    <ol v-if="section.items?.length" class="response-list" :class="{ 'is-preces-list': section.title === 'Preces' }">
      <li
        v-for="(item, index) in section.items"
        :key="`${section.title}-${index}`"
        v-html="renderPrayerText(item, { postureInstructionsEnabled })"
      />
    </ol>
  </section>
</template>
