import { escapeHtml } from './text'

/**
 * Cifra de guitarra: letra con los acordes puestos en el sitio exacto donde se tocan, como
 * cualquier cancionero de guitarra en papel. Formato de entrada tipo ChordPro: el acorde entre
 * corchetes justo delante de la sílaba/palabra donde se toca, p. ej.:
 *   [DO]Vienen con ale[SOL]gría, vienen con ale[DO]gría
 * Estrofas separadas por línea en blanco (\n\n), versos por salto simple (\n). Pedido de Lucas
 * (30/08/2026, cantos de Misa): "acordes puestos sobre el texto en el lugar correcto".
 *
 * Se renderiza en fuente monoespaciada (como cualquier cifra real) para que la posición de cada
 * acorde, calculada en caracteres, coincida visualmente con la posición sobre la letra --
 * cualquier fuente proporcional rompería la alineación.
 */

interface ParsedChordLine {
  chordLine: string
  textLine: string
}

function parseChordLine(line: string): ParsedChordLine {
  let textLine = ''
  let chordLine = ''
  let index = 0

  while (index < line.length) {
    if (line[index] === '[') {
      const end = line.indexOf(']', index)
      if (end === -1) {
        // '[' suelto sin cierre: no es un acorde, se deja como texto literal.
        textLine += line[index]
        index += 1
        continue
      }

      const chord = line.slice(index + 1, end)
      while (chordLine.length < textLine.length) {
        chordLine += ' '
      }
      if (chordLine.length > 0 && !chordLine.endsWith(' ')) {
        // Dos acordes que caerian pegados ("SOL" + "DO" -> "SOLDO") se leen como un acorde
        // inexistente. Pasa cuando el ultimo acorde del verso cuelga mas alla del final de la
        // letra y queda arrimado al anterior. Un espacio de separacion desplaza el segundo un
        // caracter, que es mucho menos malo que un acorde ilegible.
        chordLine += ' '
      }
      chordLine += chord
      index = end + 1
      continue
    }

    textLine += line[index]
    index += 1
  }

  return { chordLine, textLine: textLine.trimEnd() }
}

function renderChordSheetLine(line: string): string {
  const { chordLine, textLine } = parseChordLine(line)

  if (!chordLine.trim()) {
    // Verso sin ningún acorde propio (repite el de antes): solo la línea de letra, sin
    // desperdiciar una línea de espacios en blanco encima.
    return `<span class="chord-sheet-text-only">${escapeHtml(textLine)}</span>\n`
  }

  return `<span class="chord-sheet-chords">${escapeHtml(chordLine)}</span>\n<span class="chord-sheet-text">${escapeHtml(textLine)}</span>\n`
}

export function renderChordSheet(text: string): string {
  const stanzas = text.trim().split(/\n{2,}/)

  return [
    '<div class="chord-sheet">',
    stanzas
      .map(
        (stanza) =>
          `<pre class="chord-sheet-stanza">${stanza
            .split('\n')
            .map(renderChordSheetLine)
            .join('')}</pre>`,
      )
      .join(''),
    '</div>',
  ].join('')
}
