/**
 * Coordinación entre el service worker y la app: cuándo es seguro recargar.
 *
 * El SW va en modo `autoUpdate`: en cuanto hay un despliegue nuevo, se instala, toma el
 * control (skipWaiting + clientsClaim) y `virtual:pwa-register` recarga la página para que
 * el código viejo no siga pidiendo trozos que la caché nueva ya borró.
 *
 * El problema es CUÁNDO recarga. Esta app se usa para grabar el vídeo diario de los Laudes:
 * una recarga a mitad de una grabación de varios minutos la tira entera. Por eso el reload
 * no es automático a secas — se aplaza mientras la app está "ocupada" (grabando o con el
 * auto-scroll en marcha) y se dispara en cuanto deja de estarlo.
 *
 * Y al revés: como la app se abre y se deja abierta, se comprueba si hay versión nueva cada
 * hora y cada vez que vuelve a primer plano, para que un despliegue no tarde días en llegar.
 */

/** Cada cuánto se le pregunta al servidor si hay una versión nueva. */
const INTERVALO_COMPROBACION_MS = 60 * 60 * 1000

let ocupado = false
let recargaPendiente = false

function recargar(): void {
  window.location.reload()
}

/**
 * Marca la app como ocupada (grabando vídeo, auto-scroll en marcha…). Mientras lo esté,
 * una actualización del service worker no recarga la página; lo hará al liberarse.
 */
export function marcarAppOcupada(valor: boolean): void {
  ocupado = valor
  if (!ocupado && recargaPendiente) {
    recargaPendiente = false
    recargar()
  }
}

/** Llamado por el registro del SW cuando ya hay una versión nueva activa. */
export function solicitarRecargaPorActualizacion(): void {
  if (ocupado) {
    recargaPendiente = true
    return
  }
  recargar()
}

/** Comprobaciones periódicas de versión nueva (silenciosas: si no hay red, no pasa nada). */
export function programarComprobacionDeActualizaciones(
  registro: ServiceWorkerRegistration | undefined,
): void {
  if (!registro) {
    return
  }

  const comprobar = (): void => {
    if (navigator.onLine === false) {
      return
    }
    void registro.update().catch(() => {
      // Sin conexión o servidor caído: se reintenta en la siguiente ronda.
    })
  }

  setInterval(comprobar, INTERVALO_COMPROBACION_MS)
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') {
      comprobar()
    }
  })
  window.addEventListener('online', comprobar)
}
