import { Capacitor } from '@capacitor/core'
import { CapacitorUpdater } from '@capgo/capacitor-updater'

/**
 * Actualización en vivo del APK (Lucas, 04/11/2026: "los cambios quiero que apliquen a todos los
 * que accedan al link, no solo a mí" y sin APK nuevo por cada cambio).
 *
 * El APK lleva la app empaquetada (reza sin conexión). Al abrirse con red, mira `version.json` de
 * la web publicada; si es MÁS NUEVA que esta compilación, baja `bundle.zip` (lo publica
 * `app:deploy`) y lo deja como siguiente contenido. Se activa cuando la app pasa a segundo plano o
 * se reabre, nunca a mitad de una grabación. Sin red o ante cualquier fallo, no pasa nada: sigue
 * con lo que tiene. El origen sigue siendo https://localhost, así que los ajustes guardados no se
 * pierden. Solo los cambios NATIVOS (plugins, permisos) siguen pidiendo un APK nuevo.
 */
const URL_PUBLICADA = 'https://lucasague.github.io/liturgiadelashoras/'
const INTERVALO_MS = 30 * 60 * 1000

async function buscarActualizacion(): Promise<void> {
  if (navigator.onLine === false) {
    return
  }

  const respuesta = await fetch(`${URL_PUBLICADA}version.json?t=${Date.now()}`, { cache: 'no-store' })
  if (!respuesta.ok) {
    return
  }

  const { builtAt } = (await respuesta.json()) as { builtAt?: number }
  if (typeof builtAt !== 'number' || builtAt <= __BUILD_AT__) {
    return
  }

  const ultima = Number(localStorage.getItem('laudes:ota-descargada') ?? 0)
  if (builtAt <= ultima) {
    return
  }

  const bundle = await CapacitorUpdater.download({ url: `${URL_PUBLICADA}bundle.zip`, version: String(builtAt) })
  await CapacitorUpdater.next({ id: bundle.id })
  localStorage.setItem('laudes:ota-descargada', String(builtAt))
}

export function iniciarActualizacionEnVivo(): void {
  if (!Capacitor.isNativePlatform()) {
    return
  }

  // Sin esto el plugin da por mala la versión recién activada y vuelve a la anterior.
  void CapacitorUpdater.notifyAppReady().catch(() => undefined)

  const comprobar = (): void => {
    buscarActualizacion().catch(() => {
      // Sin red o servidor caído: se sigue con lo que hay.
    })
  }

  comprobar()
  window.setInterval(comprobar, INTERVALO_MS)
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') {
      comprobar()
    }
  })
}
