import type { EditableMode, StanzaLayout } from './stanza-edit'

const htmlTagPattern = /<\/?[a-z][\s\S]*>/i

export function escapeHtml(value: string): string {
  return value
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#039;')
}

function renderInline(value: string): string {
  return value
    .replace(/^\[\[ANTIPHON\]\]\s*(.*)$/gm, '<span class="antiphon-line"><span class="rubric">Ant.</span> $1</span>')
    .replace(/\[\[REPEATED_?ANTIPHON\]\]\s*([^<\n\r]*)/g, '<span class="repeated-antiphon"><span class="rubric">R.</span> $1</span>')
    .replace(/^\[\[READING_REFERENCE\]\]\s*(.*)$/gm, '<span class="reading-reference-line">$1</span>')
    .replace(/^\[\[MASS_READING_PROCLAMATION\]\]\s*(.*)$/gm, '<span class="mass-reading-proclamation"><span class="rubric">Lector.</span> $1</span>')
    .replace(/\[\[RESPONSORY_SPLIT\]\]/g, '<span class="responsory-split-mark" aria-hidden="true">|</span>')
    .replace(/\$([^$]+)\$/g, (_match, text: string) => {
      const rubricClass = isPostureInstructionText(text) ? 'rubric posture-instruction' : 'rubric'

      return `<span class="${rubricClass}">${text}</span>`
    })
    .replace(/_([^_]+)_/g, '<em>$1</em>')
    .replace(/(^|\n)\s*(V\.|R\.|Ant\.|\u2123\.|\u211F\.)/g, '$1<span class="rubric">$2</span>')
}

export type SingingNotationMode = 2 | 3 | 4

export interface RenderPrayerTextOptions {
  singingNotationMode?: SingingNotationMode
  minimalSingingNotation?: boolean
  /** false: oculta el texto de las indicaciones posturales (Nos ponemos en pie, Nos sentamos...),
   * conservando solo el símbolo † de la señal de la cruz. Por defecto (undefined/true) se muestran. */
  postureInstructionsEnabled?: boolean
  /** true solo en la sección "Himno": habilita el reparto de una estrofa larga en DOS pasadas de
   * la melodía, con marca de reinicio entre ellas (ver `melodyPassCandidates`). Los salmos y
   * cánticos se quedan como estaban: ahí una estrofa larga es rutina, no una excepción que
   * haya que señalar. */
  hymnNotation?: boolean
  /** true: subraya las sílabas que Lucas marca a mano (ver `underlineCustomSyllables`). Solo con el cántico
   * para el que se pidieron (el descendente de cuatro). */
  syllableMarks?: boolean
  /** Repartos que Lucas ha hecho él mismo en el modo edición de estrofas (clave: `stanzaKey`), en el
   * himno, los salmos y los cánticos. Cuentan a 2, 3 o 4 voces, y van por encima de la tabla
   * `CUSTOM_FOUR_VOICE_STANZAS`, de las listas de versos partidos y del algoritmo. */
  stanzaEdits?: Record<string, StanzaLayout>
  /** true: modo edición encendido; cada estrofa cantada va envuelta en un `.stanza-edit` con su
   * clave y su reparto actual en `data-*`, para poder tocarla. */
  stanzaEditMode?: boolean
  /** Qué texto es (la cita del salmo o cántico): solo entra en la clave del Gloria, que es igual en
   * todos (ver `stanzaKey`). */
  stanzaEditScope?: string
}

/** Contexto de la SECCIÓN entera (no de una estrofa suelta) que necesita el motor de notación.
 * Hace falta porque una decisión de estrofa puede depender de sus hermanas: una estrofa de 7
 * versos solo se canta en dos pasadas si en el mismo himno hay estrofas de 8. */
interface NotationContext {
  hymnNotation: boolean
  /** Versos contables de cada estrofa de la sección, ya en la unidad que usa el modo
   * (en modo 3, después de fundir los versos-fragmento de una sola palabra). */
  stanzaLineCounts: number[]
}

interface NotationGroup {
  label: string
  lines: string[]
}

interface NotationChunk {
  groups: NotationGroup[]
  /** true en la 2ª (y siguientes) pasada de la melodía dentro de una MISMA estrofa: es donde
   * la canción vuelve a empezar y donde va la marquita. Ver `melodyPassCandidates`. */
  passRestart?: boolean
}

interface NotationCandidate {
  chunks: NotationChunk[]
  hardJoins: number
  pattern: string
  score: number
}

interface ParagraphNotationPlan {
  chunks?: NotationChunk[]
  hidePlainLabels?: boolean
}

interface RenderNotationOptions {
  postureInstructionsEnabled?: boolean
  hideLabels?: boolean
  minimal?: boolean
  mode?: SingingNotationMode
}

function isAntiphonLine(line: string): boolean {
  return line.includes('antiphon-line') || line.includes('repeated-antiphon')
}

function normalizedLine(value: string): string {
  return value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
}

function normalizedFormulaLine(value: string): string {
  return normalizedLine(value.replace(/<[^>]*>/g, ' '))
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
}

const STANDARD_GLORIA_PATRI_TEXT =
  'gloria al padre y al hijo y al espiritu santo como era en el principio ahora y siempre por los siglos de los siglos amen'
const HEAD_BOW_INSTRUCTION_TEXT = 'Inclinamos la cabeza mientras decimos:'

export function isStandardGloriaPatriStanza(lines: string[]): boolean {
  const normalized = lines.map(normalizedFormulaLine).filter(Boolean)

  return normalized.length > 0 && normalized.join(' ') === STANDARD_GLORIA_PATRI_TEXT
}

function groupsFromLabels(labels: string[], lines: string[]): NotationGroup[] {
  return labels
    .map((label, index) => ({ label, lines: lines[index] ? [lines[index]] : [] }))
    .filter((group) => group.lines.length)
}

// Las comillas de cierre tras la puntuación («…pies.», "…mío,") no ocultan la pausa: el texto
// llega ya escapado por escapeHtml, así que la comilla recta es `&quot;`.
const closingQuoteHtml = '(?:"|&quot;|»|”)?'
const sentenceEndPattern = new RegExp(`[.!?]${closingQuoteHtml}\\s*$`)
const clauseEndPattern = new RegExp(`[.;:!?]${closingQuoteHtml}\\s*$`)
const commaEndPattern = new RegExp(`,${closingQuoteHtml}\\s*$`)

function lineJoinPenalty(line: string): number {
  const trimmed = line.trim()

  if (clauseEndPattern.test(trimmed)) {
    return 10000
  }

  if (commaEndPattern.test(trimmed)) {
    return 8
  }

  return 0
}

// Un punto final (o ! ?) pesa más que un ";" o ":" al decidir dónde va la flexa a 2 voces: un
// versículo cantado "F 1 2" puede llevar dentro un punto y coma, pero no debería cruzar una frase
// entera. Solo lo usa `candidateFromTwosChunks`; en modos 3/4 sigue mandando `lineJoinPenalty`.
function sentenceEndPenalty(line: string): number {
  return sentenceEndPattern.test(line.trim()) ? 5000 : 0
}

function quotedPhraseJoinBonus(leftLine: string, rightLine: string): number {
  const left = leftLine.trim()
  const right = rightLine.trim()
  // Una línea que abre Y cierra su propia cita («No hay Dios.») no deja nada abierto hacia la
  // siguiente, así que no gana el bono de "mantener la cita junta".
  const leftClosesOwnQuote = /[»”](?:[,;:.!?])?$/.test(left) || /(?:"|&quot;)(?:[,;:.!?])?$/.test(left)
  const leftOpensQuote = (/[«“]/.test(left) || /^(?:"|&quot;)/.test(left)) && !leftClosesOwnQuote
  const rightClosesQuote = /[»”]/.test(right) || /(?:"|&quot;)$/.test(right)

  if (leftOpensQuote && rightClosesQuote) {
    return -220
  }

  if (leftOpensQuote || rightClosesQuote) {
    return -90
  }

  return 0
}

function linePairJoinScore(leftLine: string, rightLine: string): number {
  return lineJoinPenalty(leftLine) + groupLength([leftLine, rightLine]) * 0.08 + quotedPhraseJoinBonus(leftLine, rightLine)
}

function groupLength(lines: string[]): number {
  return lines.join(' ').replace(/\s+/g, '').length
}

function groupJoinScore(lines: string[]): number {
  if (lines.length <= 1) {
    return 0
  }

  return lines
    .slice(0, -1)
    .reduce((score, line, index) => score + linePairJoinScore(line, lines[index + 1]), 0)
}

function chunkJoinScore(chunks: NotationChunk[]): number {
  return chunks.reduce((score, chunk) => {
    let lineOffset = 0

    return (
      score +
      chunk.groups.reduce((groupScore, group) => {
        const positionPenalty = group.lines.length > 1 ? lineOffset * 0.12 : 0
        lineOffset += group.lines.length

        return groupScore + groupJoinScore(group.lines) + positionPenalty
      }, 0)
    )
  }, 0)
}

function chunkHardJoinCount(chunks: NotationChunk[]): number {
  return chunks.reduce(
    (count, chunk) =>
      count +
      chunk.groups.reduce((groupCount, group) => {
        if (group.lines.length <= 1) {
          return groupCount
        }

        return (
          groupCount +
          group.lines
            .slice(0, -1)
            .filter((line) => lineJoinPenalty(line) >= 10000)
            .length
        )
      }, 0),
    0,
  )
}

function candidateFromChunks(pattern: string, chunks: NotationChunk[]): NotationCandidate {
  return {
    chunks,
    hardJoins: chunkHardJoinCount(chunks),
    pattern,
    score: chunkJoinScore(chunks),
  }
}

// `chunkJoinScore`/`chunkHardJoinCount` puntúan uniones DENTRO de un mismo grupo (líneas
// fusionadas). Las parejas de `buildTwosChunks` no fusionan nada: cada mitad ('1' y '2')
// es su propio grupo de una sola línea, para poder etiquetarlas por separado — así que esas
// funciones siempre dan 0 ahí y no sirven para elegir dónde va la flexa. Esta variante
// aplana cada chunk a sus líneas reales para puntuar la pareja como unidad, que es lo que
// de verdad hace falta para decidir si conviene romper la estrofa antes o después de un
// punto y coma.
//
// La unidad musical que se puntúa NO es el chunk sino el versículo cantado: la flexa (F) va
// siempre pegada a la pareja que le sigue ("F 1 2" es un solo versículo con tres miembros,
// nunca "1 2 F"). Por eso el chunk F-solo se fusiona aquí con el chunk siguiente antes de
// puntuar. Sin esto, una estrofa de 5 versos con la frase partida tras el verso 3 ("a, b, c. /
// d, e.") se resolvía como "1 2 F 1 2" — el punto del verso 3 caía entre F y 1, que ninguno de
// los dos candidatos puntuaba, y decidía un detalle irrelevante (una coma, la longitud). Cantado
// eso rompe la frase; lo correcto es "F 1 2 | 1 2" (Lucas, 01/09/2026, cántico de Ana:
// "El Señor desbarata a sus contrarios…").
function candidateFromTwosChunks(pattern: string, chunks: NotationChunk[]): NotationCandidate {
  const flatChunks: string[][] = []
  let pendingFree: string[] | undefined

  for (const chunk of chunks) {
    const lines = chunk.groups.flatMap((group) => group.lines)
    const isFreeOnly = chunk.groups.length === 1 && chunk.groups[0].label === 'F'

    if (isFreeOnly) {
      pendingFree = lines
      continue
    }

    flatChunks.push(pendingFree ? [...pendingFree, ...lines] : lines)
    pendingFree = undefined
  }

  if (pendingFree) {
    flatChunks.push(pendingFree)
  }

  return {
    chunks,
    hardJoins: flatChunks.reduce(
      (count, lines) =>
        count + (lines.length <= 1 ? 0 : lines.slice(0, -1).filter((line) => lineJoinPenalty(line) >= 10000).length),
      0,
    ),
    pattern,
    score: flatChunks.reduce(
      (score, lines) =>
        score + groupJoinScore(lines) + lines.slice(0, -1).reduce((extra, line) => extra + sentenceEndPenalty(line), 0),
      0,
    ),
  }
}

function candidateFromGroupSizes(
  pattern: string,
  lines: string[],
  labels: string[],
  sizes: number[],
  scoreAdjustment = 0,
): NotationCandidate {
  const candidate = candidateFromChunks(pattern, chunksFromGroupSizes(lines, labels, sizes))

  return {
    ...candidate,
    score: candidate.score + scoreAdjustment,
  }
}

function buildTwosChunks(lines: string[], leadingFree: boolean): NotationChunk[] {
  const chunks: NotationChunk[] = []

  function pushPair(pair: string[]): void {
    chunks.push({ groups: groupsFromLabels(['1', '2'], pair) })
  }

  function pushFreePair(items: string[]): void {
    if (items[0]) {
      chunks.push({ groups: [{ label: 'F', lines: [items[0]] }] })
    }

    const pair = items.slice(1)
    if (pair.length) {
      pushPair(pair)
    }
  }

  if (lines.length % 2 === 0) {
    for (let index = 0; index < lines.length; index += 2) {
      pushPair(lines.slice(index, index + 2))
    }

    return chunks
  }

  if (leadingFree) {
    pushFreePair(lines.slice(0, 3))

    for (let index = 3; index < lines.length; index += 2) {
      pushPair(lines.slice(index, index + 2))
    }

    return chunks
  }

  for (let index = 0; index < lines.length - 3; index += 2) {
    pushPair(lines.slice(index, index + 2))
  }

  pushFreePair(lines.slice(-3))
  return chunks
}

function labelsForShortModeFour(size: number): string[] {
  if (size <= 1) {
    return ['1']
  }

  if (size === 2) {
    return ['1', '4']
  }

  if (size === 3) {
    return ['1', '2', '4']
  }

  return ['1', '2', '3', '4']
}

function labelsForMode(mode: SingingNotationMode, lineCount: number): string[] {
  if (mode === 3 && lineCount === 2) {
    return ['1', '3']
  }

  return mode === 2
    ? ['1', '2']
    : mode === 3
      ? ['1', '2', '3']
      : ['1', '2', '3', '4']
}

function composeGroupSizes(total: number, groupCount: number): number[][] {
  const values: number[][] = []
  const maxGroupSize = total <= groupCount * 2 ? 2 : Math.max(2, Math.ceil(total / groupCount) + 1)

  function push(current: number[], remaining: number, groupsLeft: number): void {
    if (groupsLeft === 0) {
      if (remaining === 0) {
        values.push(current)
      }
      return
    }

    const minForRest = groupsLeft - 1
    const max = Math.min(maxGroupSize, remaining - minForRest)
    for (let size = 1; size <= max; size += 1) {
      push([...current, size], remaining - size, groupsLeft - 1)
    }
  }

  push([], total, groupCount)
  return values
}

function chunksFromGroupSizes(lines: string[], labels: string[], sizes: number[]): NotationChunk[] {
  let offset = 0

  return [
    {
      groups: sizes
        .map((size, index) => {
          const groupLines = lines.slice(offset, offset + size)
          offset += size

          return {
            label: labels[index] ?? String(index + 1),
            lines: groupLines,
          }
        })
        .filter((group) => group.lines.length),
    },
  ]
}

function mergedGroupLength(lines: string[], startIndex: number): number {
  return groupLength(lines.slice(startIndex, startIndex + 2))
}

function modeThreeFourLineCandidates(lines: string[]): NotationCandidate[] {
  const leading = candidateFromGroupSizes('2-1-1', lines, ['1', '2', '3'], [2, 1, 1])
  const middle = candidateFromGroupSizes('1-2-1', lines, ['1', '2', '3'], [1, 2, 1])
  const trailing = candidateFromGroupSizes('1-1-2', lines, ['1', '2', '3'], [1, 1, 2])
  const alternativeShorterLength = Math.min(mergedGroupLength(lines, 1), mergedGroupLength(lines, 2))
  const leadingTooLong = mergedGroupLength(lines, 0) > alternativeShorterLength * 2

  if (!leadingTooLong && leading.hardJoins === 0) {
    return [
      { ...leading, score: leading.score - 120 },
      middle,
      trailing,
    ]
  }

  return [leading, middle, trailing]
}

/** Himno, estrofa (o bloque) de cuatro versos cantada con la melodía de tres: se unen SIEMPRE los
 * dos primeros, "(1+2), 3, 4" (Lucas, 29/10/2026, himno del 30/10: "deben ser los dos primeros
 * versículos los que se unan y no los dos últimos"). Antes mandaba la puntuación (un primer verso
 * que cierra en ; o . pasaba a 1-1-2); en el himno ya no: el metro manda más que la pausa. Los
 * repartos que Lucas dicta a mano (`CUSTOM_FOUR_VOICE_STANZAS`) siguen por encima de esto. */
function hymnModeThreeFourLineCandidates(lines: string[]): NotationCandidate[] {
  return [candidateFromGroupSizes('2-1-1', lines, ['1', '2', '3'], [2, 1, 1])]
}

/** A 4 voces, estrofa de más de cuatro versos (que no sea múltiplo de cuatro): las uniones van al
 * COMIENZO de la estrofa (Lucas, 29/10/2026, segundo salmo del 30/10, Habacuc 3: "las uniones de
 * los versículos también deben venir al comienzo"). Reparto equilibrado con los grupos gordos
 * delante: 5 → 2-1-1-1, 6 → 2-2-1-1, 7 → 2-2-2-1, 9 → 3-2-2-2. Antes se puntuaba cada reparto
 * por la puntuación de los versos y solía unir los del final. */
function leadingMergeGroupSizes(total: number, groupCount: number): number[] {
  const base = Math.floor(total / groupCount)
  const extra = total % groupCount

  return Array.from({ length: groupCount }, (_, index) => base + (index < extra ? 1 : 0))
}

function uniqueCandidates(candidates: NotationCandidate[]): NotationCandidate[] {
  const byPattern = new Map<string, NotationCandidate>()

  for (const candidate of candidates) {
    const existing = byPattern.get(candidate.pattern)
    if (!existing || candidate.score < existing.score) {
      byPattern.set(candidate.pattern, candidate)
    }
  }

  return [...byPattern.values()]
}

function isBenedictusSalvationStanza(lines: string[]): boolean {
  if (lines.length !== 5) {
    return false
  }

  const normalized = lines.map(normalizedLine)

  return (
    normalized[0].startsWith('es la salvacion') &&
    normalized[1].startsWith('y de la mano') &&
    normalized[3].startsWith('recordando') &&
    normalized[4].startsWith('y el juramento')
  )
}

function isBenedictusProphetStanza(lines: string[]): boolean {
  if (lines.length !== 5) {
    return false
  }

  const normalized = lines.map((line) => normalizedLine(line).trim())

  return (
    normalized[0].startsWith('y a ti, nino') &&
    normalized[1].startsWith('porque iras delante del senor') &&
    normalized[2].startsWith('a preparar sus caminos') &&
    normalized[3].startsWith('anunciando a su pueblo la salvacion') &&
    normalized[4].startsWith('el perdon de sus pecados')
  )
}

function isPsalm50BloodStanza(lines: string[]): boolean {
  if (lines.length !== 5) {
    return false
  }

  const normalized = lines.map((line) => normalizedLine(line).trim())

  return (
    normalized[0].startsWith('librame de la sangre') &&
    normalized[1].startsWith('dios salvador mio') &&
    normalized[2].startsWith('y cantara mi lengua') &&
    normalized[3].startsWith('senor, me abriras los labios') &&
    normalized[4].startsWith('y mi boca proclamara tu alabanza')
  )
}

/** Salmo 41/42, "tiene sed de Dios...": decisión explícita de Lucas (30/08/2026) sobre uno de
 * los candidatos de fusión que catalogó un subagente. A 2 voces, los versos 1-2 (cortísimos) se
 * cantan unidos como flexa/libre, y los versos 3-4 (normales) se reparten como las 2 voces
 * reales -- no el "2 y 2" estándar que aplicaría por defecto. Solo esta estrofa concreta, solo
 * en modo 2 (Lucas: "cantando cántico de 2, siempre"). Ver memoria de proyecto
 * candidatos-fusion-versos-cortos-2-voces. */
function isPsalmThirstForGodStanza(lines: string[]): boolean {
  if (lines.length !== 4) {
    return false
  }

  const normalized = lines.map((line) => normalizedLine(line).trim())

  return (
    normalized[0].startsWith('tiene sed de dios') &&
    normalized[1].startsWith('del dios vivo') &&
    normalized[2].includes('cuando entrare a ver') &&
    normalized[3].startsWith('el rostro de dios')
  )
}

/** Salmo 86, «Él la ha cimentado sobre el monte santo…» (Lucas, 04/11/2026, Laudes del 5/11): a 4 voces
 * se canta por parejas con flexa. Estrofas de 3 y de 6: F + los dos primeros unidos, luego los dos
 * siguientes unidos, y los dos siguientes (en la de 3, el tercero va suelto). Estrofa de 4: los dos
 * pares unidos (1+2, 3+4). */
function psalm86PairsKind(lines: string[]): 3 | 4 | 6 | undefined {
  const first = normalizedLine(lines[0] ?? '').trim()

  if (lines.length === 3 && (first.startsWith('el la ha cimentado sobre el monte santo') || first.startsWith('se dira de sion'))) {
    return 3
  }
  if (lines.length === 6 && first.replace(/^[¡!]/, '').startsWith('que pregon tan glorioso para ti')) {
    return 6
  }
  if (lines.length === 4 && first.startsWith('el senor escribira en el registro de los pueblos')) {
    return 4
  }

  return undefined
}

function chunksForPsalm86Pairs(lines: string[], kind: 3 | 4 | 6): NotationChunk[] {
  // Estrofa de 4 (Lucas, 04/11/2026): F en el 1.º, el 2.º suelto, 3.º+4.º unidos.
  if (kind === 4) {
    return [
      { groups: [{ label: 'F', lines: [lines[0]] }] },
      { groups: [{ label: '', lines: [lines[1]] }, { label: '', lines: [lines[2], lines[3]] }] },
    ]
  }

  const rest: NotationGroup[] =
    kind === 3
      ? [{ label: '', lines: [lines[2]] }]
      : [{ label: '', lines: [lines[2], lines[3]] }, { label: '', lines: [lines[4], lines[5]] }]

  return [{ groups: [{ label: 'F', lines: [lines[0], lines[1]] }] }, { groups: rest }]
}

function chunksForPsalmThirstForGodStanza(lines: string[]): NotationChunk[] {
  return [
    { groups: [{ label: 'F', lines: [lines[0], lines[1]] }] },
    { groups: groupsFromLabels(['1', '2'], [lines[2], lines[3]]) },
  ]
}

/** Salmo 50, «Los sacrificios no te satisfacen…» (Lucas, 01/11/2026, Laudes del 2/11): en 3 y 4 voces
 * «Los sacrificios no te satisfacen» NO se une a «si te ofreciera un holocausto» (la puntuación
 * genérica los juntaba); lo que sí va unido son los dos últimos, «un corazón quebrantado y humillado» +
 * «tú no lo desprecias». 4 voces: 1-1-1-2. 3 voces: 1-2-2. */
function isPsalm50SacrificeSpiritStanza(lines: string[]): boolean {
  if (lines.length !== 5) {
    return false
  }

  const normalized = lines.map((line) => normalizedLine(line).trim())

  return (
    normalized[0].startsWith('los sacrificios no te satisfacen') &&
    normalized[1].startsWith('si te ofreciera un holocausto') &&
    normalized[2].startsWith('mi sacrificio es un espiritu quebrantado') &&
    normalized[3].startsWith('un corazon quebrantado') &&
    normalized[4].startsWith('tu no lo desprecias')
  )
}

function isPsalm50SionSacrificesStanza(lines: string[]): boolean {
  if (lines.length !== 5) {
    return false
  }

  const normalized = lines.map((line) => normalizedLine(line).trim())

  return (
    normalized[0].includes('favorece a sion') &&
    normalized[1].includes('murallas de jerusalen') &&
    normalized[2].startsWith('entonces aceptaras los sacrificios rituales') &&
    normalized[3].startsWith('ofrendas y holocaustos') &&
    normalized[4].includes('se inmolaran novillos')
  )
}

function mergeLinesToGroups(lines: string[], groupCount: number): NotationChunk {
  const rawGroups = lines.map((line) => [line])

  while (rawGroups.length > groupCount) {
    const hasSinglePair = rawGroups.some((group, index) => group.length === 1 && rawGroups[index + 1]?.length === 1)
    let bestIndex = 0
    let bestScore = Number.POSITIVE_INFINITY

    for (let index = 0; index < rawGroups.length - 1; index += 1) {
      const left = rawGroups[index]
      const right = rawGroups[index + 1]
      const alreadyMerged = left.length > 1 || right.length > 1

      if (hasSinglePair && alreadyMerged) {
        continue
      }

      const alreadyMergedPenalty = alreadyMerged ? 10000 : 0
      const trailingEdgePenalty = index === rawGroups.length - 2 ? 8 : 0
      const score =
        linePairJoinScore(left[left.length - 1], right[0]) +
        alreadyMergedPenalty +
        trailingEdgePenalty

      if (score < bestScore) {
        bestScore = score
        bestIndex = index
      }
    }

    rawGroups.splice(bestIndex, 2, [...rawGroups[bestIndex], ...rawGroups[bestIndex + 1]])
  }

  return {
    groups: rawGroups.map((groupLines, index) => ({
      label: String(index + 1),
      lines: groupLines,
    })),
  }
}

function chunkByThrees(lines: string[]): NotationChunk[] {
  if (lines.length <= 3) {
    return [{ groups: groupsFromLabels(labelsForMode(3, lines.length), lines) }]
  }

  if (lines.length % 3 === 0) {
    const chunks: NotationChunk[] = []

    for (let index = 0; index < lines.length; index += 3) {
      chunks.push({ groups: groupsFromLabels(['1', '2', '3'], lines.slice(index, index + 3)) })
    }

    return chunks
  }

  return [mergeLinesToGroups(lines, 3)]
}

function chunkByFours(lines: string[]): NotationChunk[] {
  if (lines.length <= 4) {
    return [{ groups: groupsFromLabels(labelsForShortModeFour(lines.length), lines) }]
  }

  if (isBenedictusSalvationStanza(lines)) {
    return [
      {
        groups: [
          { label: '1', lines: [lines[0]] },
          { label: '2', lines: [lines[1]] },
          { label: '3', lines: [lines[2]] },
          { label: '4', lines: [lines[3], lines[4]] },
        ],
      },
    ]
  }

  if (isBenedictusProphetStanza(lines)) {
    return [
      {
        groups: [
          { label: '1', lines: [lines[0]] },
          { label: '2', lines: [lines[1], lines[2]] },
          { label: '3', lines: [lines[3]] },
          { label: '4', lines: [lines[4]] },
        ],
      },
    ]
  }

  if (isPsalm50BloodStanza(lines)) {
    return [
      {
        groups: [
          { label: '1', lines: [lines[0], lines[1]] },
          { label: '2', lines: [lines[2]] },
          { label: '3', lines: [lines[3]] },
          { label: '4', lines: [lines[4]] },
        ],
      },
    ]
  }

  if (isPsalm50SacrificeSpiritStanza(lines)) {
    return [
      {
        groups: [
          { label: '1', lines: [lines[0]] },
          { label: '2', lines: [lines[1]] },
          { label: '3', lines: [lines[2]] },
          { label: '4', lines: [lines[3], lines[4]] },
        ],
      },
    ]
  }

  if (isPsalm50SionSacrificesStanza(lines)) {
    return [
      {
        groups: [
          { label: '1', lines: [lines[0]] },
          { label: '2', lines: [lines[1]] },
          { label: '3', lines: [lines[2], lines[3]] },
          { label: '4', lines: [lines[4]] },
        ],
      },
    ]
  }

  if (lines.length % 4 === 0) {
    const chunks: NotationChunk[] = []

    for (let index = 0; index < lines.length; index += 4) {
      // Lucas, 03/11/2026: en una estrofa de 8 (o 12...) cantada de cuatro en cuatro, la marquita
      // horizontal separa cada bloque de 4 del siguiente, como en el himno.
      const chunk: NotationChunk = { groups: groupsFromLabels(['1', '2', '3', '4'], lines.slice(index, index + 4)) }
      chunks.push(index ? { ...chunk, passRestart: true } : chunk)
    }

    return chunks
  }

  return [mergeLinesToGroups(lines, 4)]
}

/** Punto donde partir en dos un verso de una sola línea, cuando se canta a 2 o 4 voces (pedido
 * de Lucas, 30/08/2026): prioriza un punto NATURAL -- una pausa de puntuación real (,;:.) -- y,
 * entre varios naturales, el más CÉNTRICO (más cerca de la mitad). Sin ningún punto natural, cae
 * al espacio entre palabras más céntrico, para no partir nunca a mitad de una palabra. Ignora
 * los espacios dentro de una etiqueta HTML (el texto ya llegó procesado por renderInline/
 * escapeHtml en renderPrayerText, así que puede traer spans de rúbrica incrustados). Devuelve -1
 * si no hay ningún espacio (una sola palabra: no se puede partir). */
function naturalSplitIndex(text: string): number {
  const center = text.length / 2
  let bestNatural: number | undefined
  let bestNaturalDistance = Number.POSITIVE_INFINITY
  let bestSpace: number | undefined
  let bestSpaceDistance = Number.POSITIVE_INFINITY
  let insideTag = false

  for (let index = 0; index < text.length; index += 1) {
    const char = text[index]

    if (char === '<') {
      insideTag = true
      continue
    }
    if (char === '>') {
      insideTag = false
      continue
    }
    if (insideTag || char !== ' ') {
      continue
    }

    const distance = Math.abs(index - center)
    if (index > 0 && /[,;:.]/.test(text[index - 1]) && distance < bestNaturalDistance) {
      bestNatural = index
      bestNaturalDistance = distance
    }
    if (distance < bestSpaceDistance) {
      bestSpace = index
      bestSpaceDistance = distance
    }
  }

  return bestNatural ?? bestSpace ?? -1
}

function withNaturalSplitMark(line: string): string {
  const index = naturalSplitIndex(line)
  if (index < 0) {
    return line
  }

  const before = line.slice(0, index).trimEnd()
  const after = line.slice(index).trimStart()

  if (!before || !after) {
    return line
  }

  return `${before} ${splitMarkHtml()} ${after}`
}

// Un verso de una sola palabra (sin contar puntuación) no da para un versículo cantado propio:
// funciona como arranque del verso siguiente. Solo se aplica en modo 3 (pedido de Lucas,
// 05/09/2026, himno del 23º domingo del T.O.: "Cristo," + "alegría del mundo," +
// "resplandor de la gloria del Padre." deben cantarse como una sola unidad porque "Cristo," por
// sí solo no es un versículo). Definición deliberadamente conservadora: si la línea cierra frase
// (. ! ?) o es la última de la estrofa, no se funde hacia adelante -- como mucho hacia atrás, y
// solo si el verso anterior no cierra frase él mismo.
function isSingleWordFragmentLine(line: string): boolean {
  const plain = line.replace(/<[^>]*>/g, '').trim()

  if (!plain || sentenceEndPattern.test(plain)) {
    return false
  }

  const stripped = plain.replace(/[¡!¿?.,;:"'«»“”‘’]/g, '').trim()

  return stripped.length > 0 && !/\s/.test(stripped)
}

function joinFragmentLines(left: string, right: string): string {
  return `${left.trimEnd()} ${right.trimStart()}`
}

function mergeThreeVoiceFragments(lines: string[]): string[] {
  if (lines.length <= 1) {
    return lines
  }

  const result: string[] = []
  let index = 0

  while (index < lines.length) {
    const line = lines[index]
    const isLast = index === lines.length - 1

    if (!isLast && isSingleWordFragmentLine(line)) {
      result.push(joinFragmentLines(line, lines[index + 1]))
      index += 2
      continue
    }

    if (isLast && isSingleWordFragmentLine(line) && result.length > 0) {
      const previous = result[result.length - 1]

      if (!sentenceEndPattern.test(previous.replace(/<[^>]*>/g, '').trim())) {
        result[result.length - 1] = joinFragmentLines(previous, line)
        index += 1
        continue
      }
    }

    result.push(line)
    index += 1
  }

  return result
}

// --- Estrofas que ocupan MÁS DE UNA PASADA de la melodía (himno; Lucas, 06/09/2026) ----------
//
// Lucas canta el himno con dos melodías: la "de tres" (tres líneas melódicas por pasada) y la
// "de cuatro". Cuando la estrofa no cabe en una pasada, su manera de resolverlo NO es estirar la
// melodía sino repetirla, y siempre pensando en bloques de CUATRO versos:
//
//   1) Estrofa de 8 versos, melodía DE TRES → dos bloques de cuatro (1-4 y 5-8) y, dentro de
//      cada bloque, sus dos primeros versos se cantan en una sola línea melódica: "(1+2), 3, 4"
//      (`hymnModeThreeFourLineCandidates`; desde el 29/10/2026 siempre los dos primeros, sin
//      mirar la puntuación), así que una estrofa de 8 se canta igual que dos estrofas de 4.
//   2) Estrofa de 8 versos, melodía DE CUATRO → dos pasadas limpias (1-4 y 5-8), sin unir nada.
//   3) Estrofa de 7 versos que CONVIVE con estrofas de 8 en el mismo himno → también dos
//      pasadas, 3+4 o 4+3; la de tres versos es la corta y en modo 4 lleva "el cuartito" (salta
//      a la 4ª línea melódica: etiquetas 1, 2, 4 — ver `labelsForShortModeFour`).
//
// Entre pasada y pasada va una marca discreta (`passRestart` → clase `is-pass-restart`).
const MELODY_PASS_BLOCK_LINES = 4
const MELODY_PASS_STANZA_LINES = MELODY_PASS_BLOCK_LINES * 2
const MELODY_PASS_SHORT_BLOCK_LINES = MELODY_PASS_BLOCK_LINES - 1
const MELODY_PASS_SHORT_STANZA_LINES = MELODY_PASS_STANZA_LINES - 1

// Criterio explícito de "lo que tenga más sentido" para decidir qué mitad de una estrofa de 7
// lleva el bloque corto: se corta donde el TEXTO ya se corta. Cuanto mejor cierre el verso que
// queda antes del corte, menos penalización. Es una tabla a propósito, para poder afinarla sin
// tocar la lógica: subir `comma` aleja el corte de las comas, bajar `enjambment` lo hace menos
// tímido ante un encabalgamiento. En empate exacto gana el primer reparto probado (3+4), que
// deja el bloque corto —y su "cuartito"— al principio.
const PASS_BOUNDARY_PENALTY = {
  /** El verso cierra frase (. ! ?): el corte es invisible al oído. */
  sentence: 0,
  /** Cierra inciso (; :): pausa real, pero la frase sigue. */
  clause: 40,
  /** Solo una coma: se puede, pero se nota. */
  comma: 90,
  /** Encabalgamiento puro: partir ahí rompe la frase por la mitad. */
  enjambment: 260,
}

function passBoundaryPenalty(line: string): number {
  const trimmed = line.replace(/<[^>]*>/g, '').trim()

  if (sentenceEndPattern.test(trimmed)) {
    return PASS_BOUNDARY_PENALTY.sentence
  }

  if (clauseEndPattern.test(trimmed)) {
    return PASS_BOUNDARY_PENALTY.clause
  }

  if (commaEndPattern.test(trimmed)) {
    return PASS_BOUNDARY_PENALTY.comma
  }

  return PASS_BOUNDARY_PENALTY.enjambment
}

/** Repartos posibles de la estrofa en pasadas de la melodía, o [] si esta estrofa se canta de
 * una sola pasada (que es lo normal y lo que había antes de todo esto). */
function melodyPassSplits(lines: string[], context: NotationContext): number[][] {
  if (!context.hymnNotation) {
    return []
  }

  if (lines.length === MELODY_PASS_STANZA_LINES) {
    return [[MELODY_PASS_BLOCK_LINES, MELODY_PASS_BLOCK_LINES]]
  }

  // Estrofa de 10 (Lucas, 24/10/2026, "Hombre quisiste hacerme…", himno del viernes de la 29ª
  // semana): tres pasadas, 4+4+2. La de dos versos lleva 1-3 (a 3 voces) o 1-4 (a 4).
  if (lines.length === MELODY_PASS_STANZA_LINES + 2) {
    return [[MELODY_PASS_BLOCK_LINES, MELODY_PASS_BLOCK_LINES, 2]]
  }

  // Estrofa de 11 (Lucas, 02/11/2026, "Señor, el día empieza…", martes de la 31ª semana): tres
  // pasadas, 4+4+3 / 4+3+4 / 3+4+4; el criterio de corte (PASS_BOUNDARY_PENALTY) elige dónde.
  if (lines.length === MELODY_PASS_STANZA_LINES + 3) {
    return [
      [MELODY_PASS_BLOCK_LINES, MELODY_PASS_BLOCK_LINES, MELODY_PASS_SHORT_BLOCK_LINES],
      [MELODY_PASS_BLOCK_LINES, MELODY_PASS_SHORT_BLOCK_LINES, MELODY_PASS_BLOCK_LINES],
      [MELODY_PASS_SHORT_BLOCK_LINES, MELODY_PASS_BLOCK_LINES, MELODY_PASS_BLOCK_LINES],
    ]
  }

  // La estrofa de 7 solo se parte si en el mismo himno hay estrofas de 8: suelta se sigue
  // cantando como siempre (una pasada larga). Es la condición que puso Lucas: "si una estrofa
  // de siete convive con otras estrofas de ocho".
  if (
    lines.length === MELODY_PASS_SHORT_STANZA_LINES &&
    context.stanzaLineCounts.includes(MELODY_PASS_STANZA_LINES)
  ) {
    return [
      [MELODY_PASS_SHORT_BLOCK_LINES, MELODY_PASS_BLOCK_LINES],
      [MELODY_PASS_BLOCK_LINES, MELODY_PASS_SHORT_BLOCK_LINES],
    ]
  }

  return []
}

/** Cómo se canta UN bloque (una pasada de la melodía) por sí solo. */
function melodyPassBlockCandidates(lines: string[], mode: 3 | 4): NotationCandidate[] {
  if (mode === 4) {
    return [
      candidateFromChunks(`p${lines.length}`, [
        { groups: groupsFromLabels(labelsForShortModeFour(lines.length), lines) },
      ]),
    ]
  }

  // Modo 3: un bloque de cuatro versos es exactamente el caso que ya resuelve
  // `modeThreeFourLineCandidates` (2-1-1 / 1-2-1 / 1-1-2, con preferencia por unir los dos
  // primeros). Un bloque de tres cae en la melodía tal cual.
  if (lines.length === MELODY_PASS_BLOCK_LINES) {
    return hymnModeThreeFourLineCandidates(lines)
  }

  return [
    candidateFromChunks(`p${lines.length}`, [
      { groups: groupsFromLabels(labelsForMode(3, lines.length), lines) },
    ]),
  ]
}

function melodyPassCandidates(
  lines: string[],
  mode: 3 | 4,
  context: NotationContext | undefined,
): NotationCandidate[] | undefined {
  if (!context) {
    return undefined
  }

  const splits = melodyPassSplits(lines, context)
  if (!splits.length) {
    return undefined
  }

  const candidates: NotationCandidate[] = []

  for (const sizes of splits) {
    let boundaryPenalty = 0
    let start = 0
    const blocks: NotationCandidate[][] = []

    for (const size of sizes) {
      blocks.push(melodyPassBlockCandidates(lines.slice(start, start + size), mode))
      start += size
      if (start < lines.length) {
        boundaryPenalty += passBoundaryPenalty(lines[start - 1])
      }
    }

    // Producto cartesiano de las opciones de cada bloque; los bloques 2..N llevan la marquita.
    let combos: NotationCandidate[] = [
      { chunks: [], hardJoins: 0, pattern: `pass-${sizes.join('-')}`, score: boundaryPenalty },
    ]

    blocks.forEach((options, index) => {
      combos = combos.flatMap((acc) =>
        options.map((option) => ({
          chunks: [
            ...acc.chunks,
            ...option.chunks.map((chunk) => (index ? { ...chunk, passRestart: true } : chunk)),
          ],
          hardJoins: acc.hardJoins + option.hardJoins,
          pattern: `${acc.pattern}${index ? '|' : ':'}${option.pattern}`,
          score: acc.score + option.score,
        })),
      )
    })

    candidates.push(...combos)
  }

  return candidates
}

function notationCandidates(
  lines: string[],
  mode: SingingNotationMode,
  context?: NotationContext,
): NotationCandidate[] {
  // Estrofa de un solo versículo cantada a 2 o 4 voces: sin esto, un verso único quedaba como
  // una sola voz "libre" sin marca visual de dónde reparte el canto entre voces. Se excluye el
  // modo 3 a propósito (no lo pidió Lucas).
  // Sin etiqueta: la F (flexa) solo tiene sentido si tras ella vienen otros dos versículos (Lucas,
  // 24/10/2026); aquí el verso partido por la barra no necesita F.
  if ((mode === 2 || mode === 4) && lines.length === 1) {
    return [candidateFromChunks('single-line-split', [{ groups: [{ label: '', lines: [withNaturalSplitMark(lines[0])] }] }])]
  }

  if (mode === 2) {
    if (lines.length <= 1) {
      return [candidateFromChunks('F', [{ groups: [{ label: 'F', lines }] }])]
    }

    if (isPsalmThirstForGodStanza(lines)) {
      return [candidateFromChunks('psalm-thirst-for-god', chunksForPsalmThirstForGodStanza(lines))]
    }

    if (lines.length % 2 === 0) {
      return [candidateFromChunks('pairs', buildTwosChunks(lines, true))]
    }

    return uniqueCandidates([
      candidateFromTwosChunks('leading-free', buildTwosChunks(lines, true)),
      candidateFromTwosChunks('trailing-free', buildTwosChunks(lines, false)),
    ])
  }

  if (mode === 3) {
    const mergedLines = mergeThreeVoiceFragments(lines)

    // Himno: estrofa que no cabe en una pasada de la melodía (8 versos, o 7 conviviendo con 8).
    // Se mide sobre `mergedLines` porque un verso-fragmento de una sola palabra no cuenta como
    // versículo cantado (be95d4b), y por tanto tampoco cuenta para llegar a los 8.
    const passCandidates = melodyPassCandidates(mergedLines, 3, context)
    if (passCandidates) {
      return passCandidates
    }

    if (mergedLines.length <= 3) {
      return [
        candidateFromChunks(`short-${mergedLines.length}`, [
          { groups: groupsFromLabels(labelsForMode(3, mergedLines.length), mergedLines) },
        ]),
      ]
    }

    if (mergedLines.length === 4) {
      return context?.hymnNotation
        ? hymnModeThreeFourLineCandidates(mergedLines)
        : modeThreeFourLineCandidates(mergedLines)
    }

    if (isPsalm50SacrificeSpiritStanza(mergedLines)) {
      return [candidateFromGroupSizes('1-2-2', mergedLines, ['1', '2', '3'], [1, 2, 2])]
    }

    if (mergedLines.length === 6) {
      return [candidateFromGroupSizes('2-2-2', mergedLines, ['1', '2', '3'], [2, 2, 2])]
    }

    if (mergedLines.length % 3 === 0) {
      return [candidateFromChunks('triples', chunkByThrees(mergedLines))]
    }

    return composeGroupSizes(mergedLines.length, 3).map((sizes) =>
      candidateFromChunks(sizes.join('-'), chunksFromGroupSizes(mergedLines, ['1', '2', '3'], sizes)),
    )
  }

  // Himno a 4 voces: estrofa de 8 (dos pasadas limpias) o de 7 conviviendo con estrofas de 8
  // (dos pasadas, una de ellas corta, con "el cuartito"). Va antes que `chunkByFours`, que
  // también parte de 4 en 4 pero sin marcar dónde vuelve a empezar la melodía.
  const passCandidates = melodyPassCandidates(lines, 4, context)
  if (passCandidates) {
    return passCandidates
  }

  const psalm86Kind = psalm86PairsKind(lines)
  if (psalm86Kind) {
    return [candidateFromChunks('psalm-86-pairs', chunksForPsalm86Pairs(lines, psalm86Kind))]
  }

  if (lines.length <= 4) {
    return [candidateFromChunks(`short-${lines.length}`, [{ groups: groupsFromLabels(labelsForShortModeFour(lines.length), lines) }])]
  }

  if (isBenedictusSalvationStanza(lines)) {
    return [candidateFromChunks('benedictus-salvation', chunkByFours(lines))]
  }

  if (isBenedictusProphetStanza(lines)) {
    return [candidateFromChunks('benedictus-prophet', chunkByFours(lines))]
  }

  if (isPsalm50BloodStanza(lines)) {
    return [candidateFromChunks('psalm-50-blood', chunkByFours(lines))]
  }

  if (isPsalm50SacrificeSpiritStanza(lines)) {
    return [candidateFromChunks('psalm-50-sacrifice-spirit', chunkByFours(lines))]
  }

  if (isPsalm50SionSacrificesStanza(lines)) {
    return [candidateFromChunks('psalm-50-sion-sacrifices', chunkByFours(lines))]
  }

  if (lines.length % 4 === 0) {
    return [candidateFromChunks('fours', chunkByFours(lines))]
  }

  const sizes = leadingMergeGroupSizes(lines.length, 4)

  return [candidateFromChunks(sizes.join('-'), chunksFromGroupSizes(lines, ['1', '2', '3', '4'], sizes))]
}

function chunkLines(lines: string[], mode: SingingNotationMode, context?: NotationContext): NotationChunk[] {
  return notationCandidates(lines, mode, context).reduce((best, candidate) => (candidate.score < best.score ? candidate : best))
    .chunks
}

function expectedLabelsForMode(mode: SingingNotationMode): string[] {
  return Array.from({ length: mode }, (_, index) => String(index + 1))
}

function isPlainChunk(chunk: NotationChunk, mode: SingingNotationMode): boolean {
  const expectedLabels = expectedLabelsForMode(mode)

  return (
    chunk.groups.length === expectedLabels.length &&
    chunk.groups.every((group, index) => group.label === expectedLabels[index] && group.lines.length === 1)
  )
}

function renderNotationChunk(chunk: NotationChunk, options: RenderNotationOptions = {}): string {
  const expectedLabels = options.mode ? expectedLabelsForMode(options.mode) : []
  const isExpectedSequence =
    expectedLabels.length > 0 &&
    chunk.groups.length === expectedLabels.length &&
    chunk.groups.every((group, index) => group.label === expectedLabels[index])
  const freeOnlyClass = chunk.groups.length === 1 && (chunk.groups[0].label === 'F' || chunk.groups[0].label === '') ? ' is-free-only' : ''
  const minimalClass = options.minimal ? ' is-minimal' : ''
  const mergedGroupsClass = chunk.groups.some((group) => group.lines.length > 1) ? ' has-merged-groups' : ''
  // La marquita de "aquí vuelve a empezar la melodía" (himno, estrofa a dos pasadas).
  const passRestartClass = chunk.passRestart ? ' is-pass-restart' : ''

  return [
    `<span class="notation-chunk${freeOnlyClass}${minimalClass}${mergedGroupsClass}${passRestartClass}">`,
    chunk.groups
      .map((group, index) => {
        const freeClass = group.label === 'F' ? ' is-free' : ''
        const mergedClass = group.lines.length > 1 ? ' is-merged' : ''
        const showMinimalFinalFour =
          options.minimal &&
          options.mode === 4 &&
          chunk.groups.length < 4 &&
          index === chunk.groups.length - 1 &&
          group.label === '4' &&
          group.lines.length === 1
        const showShortModeThreeFinalThree =
          options.mode === 3 &&
          chunk.groups.length === 2 &&
          (index === chunk.groups.length - 1 || chunk.groups.slice(index + 1).every((rest) => rest.label === '')) &&
          group.label === '3' &&
          group.lines.length === 1
        const hideNumericLabel =
          group.label !== 'F' &&
          !showMinimalFinalFour &&
          !showShortModeThreeFinalThree &&
          (options.minimal || isExpectedSequence || group.lines.length > 1 || (options.mode === 3 && chunk.groups.length === 2))
        const label = options.hideLabels || hideNumericLabel ? '' : group.label
        const labelClass = label ? ' has-label' : ''

        return [
          `<span class="notation-line-group${mergedClass}${labelClass}">`,
          `<span class="notation-label${freeClass}">${label}</span>`,
          '<span class="notation-lines">',
          group.lines.map((line) => renderSourceLine(line, options)).join(''),
          '</span>',
          '</span>',
        ].join('')
      })
      .join(''),
    '</span>',
  ].join('')
}

// Último reparto pintado por `renderNotationStanza`: el modo edición de himnos lo lee justo después
// de pintar una estrofa para saber cómo quedó (ver `renderParagraph`).
let capturedNotationChunks: NotationChunk[] | undefined

function renderNotationStanza(
  chunks: NotationChunk[],
  options: RenderPrayerTextOptions,
  extraClass = '',
): string {
  capturedNotationChunks = chunks
  return [
    `<p class="source-stanza notation-mode-${options.singingNotationMode}${extraClass}">`,
    chunks
      .map((chunk) =>
        renderNotationChunk(chunk, {
          hideLabels: isPlainChunk(chunk, options.singingNotationMode!),
          minimal: options.minimalSingingNotation,
          mode: options.singingNotationMode,
          postureInstructionsEnabled: options.postureInstructionsEnabled,
        }),
      )
      .join(''),
    '</p>',
  ].join('')
}

function splitMarkHtml(): string {
  return '<span class="responsory-split-mark" aria-hidden="true">|</span>'
}

function renderSourceLine(line: string, options: RenderPrayerTextOptions): string {
  const postureInstructionsEnabled = options.postureInstructionsEnabled !== false
  const headBowTargetClass =
    postureInstructionsEnabled && lineNeedsHeadBowInstruction(line) ? ' is-head-bow-frame-end' : ''

  return `<span class="source-line${headBowTargetClass}">${line}</span>`
}

function plainTextFromRenderedParagraph(paragraph: string): string {
  return paragraph
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
}

function isCenteredInstructionParagraph(paragraph: string): boolean {
  const text = plainTextFromRenderedParagraph(paragraph)
  const normalized = normalizedFormulaLine(text)

  return isCenteredInstructionText(normalized)
}

function isCenteredInstructionText(normalized: string): boolean {
  return (
    normalized.includes('nos ponemos en pie') ||
    normalized.includes('nos sentamos') ||
    normalized.includes('hacemos la senal de la cruz mientras decimos') ||
    normalized.includes('inclinamos la cabeza mientras decimos') ||
    normalized.includes('inclinamos la cabeza') ||
    normalized.includes('todos decimos mientras inclinamos la cabeza')
  )
}

function isPostureInstructionText(text: string): boolean {
  return isCenteredInstructionText(normalizedFormulaLine(text))
}

function isSignOfCrossInstructionParagraph(paragraph: string): boolean {
  return normalizedFormulaLine(plainTextFromRenderedParagraph(paragraph)).includes(
    'hacemos la senal de la cruz mientras decimos',
  )
}

function prependDaggerToInstruction(paragraph: string): string {
  if (paragraph.includes('†')) {
    return paragraph
  }

  return paragraph.replace(/(<span class="[^"]*\brubric\b[^"]*">)\s*/, '$1† ')
}

function moveGroupedSignOfCrossDagger(instructions: string[]): string[] {
  const signOfCrossIndex = instructions.findIndex((paragraph) => (
    isSignOfCrossInstructionParagraph(paragraph) && paragraph.includes('†')
  ))

  if (signOfCrossIndex <= 0) {
    return instructions
  }

  const moved = [...instructions]
  moved[0] = prependDaggerToInstruction(moved[0])
  moved[signOfCrossIndex] = moved[signOfCrossIndex].replace(/†\s*/, '')

  return moved
}

// Cuando se concatenan varias rúbricas (p.ej. "Nos ponemos en pie" + "Hacemos la señal de la
// cruz..."), cada una salvo la última necesita terminar en un signo de puntuación para que la
// unión con espacio no quede como "Nos ponemos en pie Hacemos..." sin punto entre medias.
function endsWithSentencePunctuation(text: string): boolean {
  return /[.!?:;†]$/.test(text.trim())
}

function appendPeriodBeforeClosingSpan(paragraph: string): string {
  const lastSpanCloseIndex = paragraph.lastIndexOf('</span>')

  if (lastSpanCloseIndex === -1) {
    return `${paragraph}.`
  }

  return `${paragraph.slice(0, lastSpanCloseIndex)}.${paragraph.slice(lastSpanCloseIndex)}`
}

function ensureInstructionPunctuation(paragraph: string): string {
  const plainText = plainTextFromRenderedParagraph(paragraph)

  if (!plainText || endsWithSentencePunctuation(plainText)) {
    return paragraph
  }

  return appendPeriodBeforeClosingSpan(paragraph)
}

function joinInstructionParagraphs(instructions: string[]): string {
  return instructions
    .map((instruction, index) => (index < instructions.length - 1 ? ensureInstructionPunctuation(instruction) : instruction))
    .join(' ')
}

function groupConsecutiveInstructionParagraphs(paragraphs: string[]): string[] {
  const grouped: string[] = []
  let index = 0

  while (index < paragraphs.length) {
    const paragraph = paragraphs[index]
    if (!isCenteredInstructionParagraph(paragraph)) {
      grouped.push(paragraph)
      index += 1
      continue
    }

    const instructions = [paragraph]
    index += 1

    while (index < paragraphs.length && isCenteredInstructionParagraph(paragraphs[index])) {
      instructions.push(paragraphs[index])
      index += 1
    }

    grouped.push(joinInstructionParagraphs(moveGroupedSignOfCrossDagger(instructions)))
  }

  return grouped
}

function headBowInstructionHtml(): string {
  return `<p class="source-stanza is-centered-instruction is-head-bow-frame-start"><span class="source-line"><span class="rubric posture-instruction">${HEAD_BOW_INSTRUCTION_TEXT}</span></span></p>`
}

function lineNeedsHeadBowInstruction(line: string): boolean {
  const normalized = normalizedFormulaLine(line)

  return (
    normalized === 'gloria al padre y al hijo y al espiritu santo' ||
    normalized === 'bendigamos al padre y al hijo con el espiritu santo'
  )
}

function needsHeadBowInstruction(lines: string[]): boolean {
  return lines.some(lineNeedsHeadBowInstruction)
}

function gloriaLineWithModeFourSplit(line: string): string {
  return line.replace(
    /(Gloria\s+al\s+Padre,\s*y\s+al\s+Hijo,?)\s+(y\s+al\s+Esp[i\u00ed]ritu\s+Santo\.?)/i,
    `$1 ${splitMarkHtml()} $2`,
  )
}

function renderGloriaStanza(lines: string[], options: RenderPrayerTextOptions): string {
  if (options.singingNotationMode === 4) {
    return [
      '<p class="source-stanza gloria-stanza is-gloria-split">',
      lines
        .map((line, index) => renderSourceLine(index === 0 ? gloriaLineWithModeFourSplit(line) : line, options))
        .join(''),
      '</p>',
    ].join('')
  }

  return renderNotationStanza(chunkLines(lines, options.singingNotationMode!), options, ' gloria-stanza')
}

