const VOICE_SPLIT_MARK = '|'

function voiceSplitKey(value: string): string {
  return normalizedFormulaLine(value.replace(/&[a-z]+;|&#\d+;/gi, ' '))
}

interface VoiceSplitVerse {
  /** Palabras (normalizadas) que van antes del corte; 0 si el verso no se parte. */
  wordsBefore: number
}

const FOUR_VOICE_SPLITS: Map<string, VoiceSplitVerse[]> = new Map(
  FOUR_VOICE_SPLIT_STANZAS.map((verses) => [
    verses.map((verse) => voiceSplitKey(verse.replace(VOICE_SPLIT_MARK, ''))).join('\n'),
    verses.map((verse) => {
      const cut = verse.indexOf(VOICE_SPLIT_MARK)
      return { wordsBefore: cut < 0 ? 0 : voiceSplitKey(verse.slice(0, cut)).split(' ').length }
    }),
  ]),
)

/** Inserta la marca `|` tras la palabra nº `wordsBefore` del verso (ya en HTML), pegada a su
 * puntuación posterior ("Dios, | defiende"). No toca nada más. */
function lineWithVoiceSplit(line: string, wordsBefore: number): string {
  const tokenPattern = /<[^>]*>|&[a-z]+;|&#\d+;|[\p{L}\p{N}]+/giu
  let words = 0
  let match: RegExpExecArray | null

  while ((match = tokenPattern.exec(line))) {
    if (/^[<&]/.test(match[0])) {
      continue
    }

    words += 1
    if (words === wordsBefore) {
      const end = match.index + match[0].length
      const punctuation = /^[,;:]*/.exec(line.slice(end))![0]
      const cut = end + punctuation.length
      return `${line.slice(0, cut)} ${splitMarkHtml()} ${line.slice(cut).trimStart()}`
    }
  }

  return line
}

/** Estrofa de la lista que se canta partida a 4 voces, o `undefined`. */
function fourVoiceSplitFor(countableLines: string[]): VoiceSplitVerse[] | undefined {
  return FOUR_VOICE_SPLITS.get(countableLines.map(voiceSplitKey).join('\n'))
}

/** Como el Gloria a 4, pero con rótulos: cada verso lleva la primera voz que lo canta; un verso
 * partido consume dos voces (1-2 en la misma línea), así la estrofa llega a 1-2-3-4. */
function renderFourVoiceSplitStanza(
  lines: string[],
  splits: VoiceSplitVerse[],
  options: RenderPrayerTextOptions,
): string {
  let voice = 1
  let lastVoice = 0
  const groups: NotationGroup[] = lines.map((line, index) => {
    const wordsBefore = splits[index].wordsBefore
    // El 4 que sigue correlativo al rótulo anterior (1-3-4) sobra: la estrofa ya llega a 4 voces.
    const followsPrevious = voice === 4 && lastVoice === 3
    const group = {
      label: followsPrevious ? '' : String(voice),
      lines: [wordsBefore ? lineWithVoiceSplit(line, wordsBefore) : line],
    }
    voice += wordsBefore ? 2 : 1
    lastVoice = voice - 1
    return group
  })

  return renderNotationStanza([{ groups }], options, ' is-voice-split')
}

