import { Capacitor, registerPlugin } from '@capacitor/core'

/** Bloquear el móvil al terminar la grabación (APK, 29/10/2026). El plugin nativo está en
 * app/android/.../BloqueoPantallaPlugin.java y se apoya en un servicio de accesibilidad que
 * Lucas activa una vez en Ajustes > Accesibilidad. Nada de esto falla hacia fuera: sin APK o
 * sin el servicio activado, devuelve bloqueado=false y la app sigue como antes. */

/** false desde el APK 2.6 (29/10/2026): el Honor no deja instalar un APK de fuera de la tienda
 * que declara un servicio de accesibilidad ("Acción bloqueada"), así que el servicio se quitó del
 * AndroidManifest. Mientras sea false no se llama al plugin nativo, el menú no enseña la opción y
 * el doble toque solo copia y manda los textos. Ponerlo a true solo con otra vía de bloqueo. */
export const BLOQUEO_PANTALLA_DISPONIBLE = false

export type MotivoSinBloqueo =
  | 'web'
  | 'no-disponible'
  | 'android-antiguo'
  | 'accesibilidad-desactivada'
  | 'android-lo-rechazo'
  | 'error'

export interface ResultadoBloqueo {
  bloqueado: boolean
  motivo?: MotivoSinBloqueo
}

export interface EstadoBloqueo {
  soportado: boolean
  activo: boolean
}

interface BloqueoPantallaPlugin {
  estado(): Promise<EstadoBloqueo>
  bloquear(): Promise<ResultadoBloqueo>
  abrirAjustes(): Promise<void>
}

const BloqueoPantalla = registerPlugin<BloqueoPantallaPlugin>('BloqueoPantalla')

export const ULTIMO_BLOQUEO_KEY = 'laudes:ultimo-bloqueo'

export async function estadoBloqueoPantalla(): Promise<EstadoBloqueo> {
  if (!Capacitor.isNativePlatform() || !BLOQUEO_PANTALLA_DISPONIBLE) return { soportado: false, activo: false }
  try {
    return await BloqueoPantalla.estado()
  } catch {
    return { soportado: false, activo: false }
  }
}

/** Bloquea si se puede. El resultado queda también en localStorage (ULTIMO_BLOQUEO_KEY) para
 * poder saber después por qué no bloqueó, sin enseñar nada en pantalla mientras se graba. */
export async function bloquearPantallaSiSePuede(): Promise<ResultadoBloqueo> {
  let resultado: ResultadoBloqueo
  if (!Capacitor.isNativePlatform()) {
    resultado = { bloqueado: false, motivo: 'web' }
  } else if (!BLOQUEO_PANTALLA_DISPONIBLE) {
    resultado = { bloqueado: false, motivo: 'no-disponible' }
  } else {
    try {
      resultado = await BloqueoPantalla.bloquear()
    } catch {
      resultado = { bloqueado: false, motivo: 'error' }
    }
  }
  try {
    localStorage.setItem(ULTIMO_BLOQUEO_KEY, JSON.stringify({ ...resultado, en: new Date().toISOString() }))
  } catch {
    // Sin localStorage no pasa nada.
  }
  return resultado
}

export async function abrirAjustesBloqueoPantalla(): Promise<void> {
  if (!Capacitor.isNativePlatform() || !BLOQUEO_PANTALLA_DISPONIBLE) return
  try {
    await BloqueoPantalla.abrirAjustes()
  } catch {
    // Si MagicOS no abre esa pantalla, Lucas llega a mano: Ajustes > Accesibilidad.
  }
}

/** Espera a que una promesa termine, pero como mucho `ms`. Nunca rechaza. */
export function esperarComoMucho(promesa: Promise<unknown>, ms: number): Promise<void> {
  return new Promise((resolve) => {
    const timer = setTimeout(resolve, ms)
    promesa.then(
      () => { clearTimeout(timer); resolve() },
      () => { clearTimeout(timer); resolve() },
    )
  })
}
