import { computed, ref } from 'vue'
import type { StanzaLayout } from './stanza-edit'
import { DATA_RAW_BASE, RELAY_URL } from './rele'

// Estado del modo edición de estrofas (himno, salmos y cánticos), compartido entre Ajustes (App.vue)
// y las secciones (PrayerSection.vue).
//
// Dónde se guarda (09/11/2026): primero en este dispositivo (localStorage), al instante, y después en
// la nube, `repartos.json` de la rama `data` de liturgiadelashoras, por el mismo relé de Cloudflare
// que guarda los cánticos (worker/, `PUT /repartos`). Así lo que Lucas reparte en el móvil vale
// también en el APK, en el PC y tras borrar datos.
//
// La nube puede llegar tarde (lección de 9310447): lo local manda mientras tanto, y al llegar se
// FUSIONA estrofa a estrofa por la hora del último cambio, nunca se sustituye. Restablecer una
// estrofa deja una marca de borrado con su hora (`layout: null`), para que el borrado viaje también
// y una copia vieja de otro dispositivo no la resucite.

export interface StanzaEditEntry {
  layout: StanzaLayout | null
  /** Hora (ms) del último cambio de esta estrofa. */
  t: number
}

export type StanzaEditEntries = Record<string, StanzaEditEntry>

const STORAGE_KEY = 'orante:repartos-estrofas'
export const STANZA_EDITS_RAW_URL = `${DATA_RAW_BASE}/repartos.json`

/** Fusión estrofa a estrofa: gana el cambio más reciente (un borrado también es un cambio). */
export function mergeStanzaEditEntries(a: StanzaEditEntries, b: StanzaEditEntries): StanzaEditEntries {
  const merged: StanzaEditEntries = { ...a }
  for (const [key, entry] of Object.entries(b)) {
    if (!merged[key] || entry.t > merged[key].t) {
      merged[key] = entry
    }
  }
  return merged
}

function isLayout(value: unknown): value is StanzaLayout {
  const layout = value as StanzaLayout
  return (
    typeof value === 'object' &&
    value !== null &&
    Array.isArray(layout.lines) &&
    layout.lines.every((line) => typeof line === 'string') &&
    Array.isArray(layout.passes) &&
    layout.passes.every(
      (pass) =>
        Array.isArray(pass) &&
        pass.every((group) => Array.isArray(group) && typeof group[0] === 'string' && Number.isInteger(group[1])),
    )
  )
}

/** Lo leído (de localStorage o de la nube), limpio: descarta lo que no tenga la forma esperada. */
export function sanitizeStanzaEditEntries(value: unknown): StanzaEditEntries {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    return {}
  }
  const clean: StanzaEditEntries = {}
  for (const [key, entry] of Object.entries(value as Record<string, unknown>)) {
    const candidate = entry as StanzaEditEntry
    if (
      typeof candidate === 'object' &&
      candidate !== null &&
      typeof candidate.t === 'number' &&
      (candidate.layout === null || isLayout(candidate.layout))
    ) {
      clean[key] = { layout: candidate.layout, t: candidate.t }
    }
  }
  return clean
}

/** Clave de la primera versión del modo edición (02-09/11/2026, solo himnos, sin nube): guardaba
 * `{ clave: reparto }` sin hora. El 09/11 se cambió de clave sin migrar y esos repartos quedaron
 * huérfanos en el móvil. Se rescatan con hora 1: cualquier cambio posterior, o la nube, gana. */
const LEGACY_STORAGE_KEY = 'orante:himno-repartos'

/** Repartos de la clave antigua, con la forma nueva. */
export function legacyStanzaEditEntries(value: unknown): StanzaEditEntries {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    return {}
  }
  const wrapped: Record<string, unknown> = {}
  for (const [key, layout] of Object.entries(value as Record<string, unknown>)) {
    wrapped[key] = { layout, t: 1 }
  }
  return sanitizeStanzaEditEntries(wrapped)
}

function readLocal(): StanzaEditEntries {
  let current: StanzaEditEntries = {}
  try {
    current = sanitizeStanzaEditEntries(JSON.parse(localStorage.getItem(STORAGE_KEY) ?? '{}'))
  } catch {
    // Nada guardado o ilegible.
  }
  try {
    const legacy = legacyStanzaEditEntries(JSON.parse(localStorage.getItem(LEGACY_STORAGE_KEY) ?? '{}'))
    return mergeStanzaEditEntries(legacy, current)
  } catch {
    return current
  }
}

function writeLocal(entries: StanzaEditEntries): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(entries))
  } catch {
    // Sin localStorage: el cambio vale mientras la app siga abierta (y va a la nube igual).
  }
}

/** Interruptor del lápiz de Ajustes. No se recuerda entre aperturas: así nunca se queda puesto
 * por descuido en una grabación. */
export const stanzaEditMode = ref(false)

const entries = ref<StanzaEditEntries>(typeof localStorage === 'undefined' ? {} : readLocal())
// Lo rescatado de la clave antigua queda ya en la clave nueva (y la nube lo recibe al abrir).
if (typeof localStorage !== 'undefined' && localStorage.getItem(LEGACY_STORAGE_KEY)) {
  writeLocal(entries.value)
}

/** Repartos vigentes (sin las marcas de borrado), por clave de `stanzaKey`. */
export const stanzaEdits = computed<Record<string, StanzaLayout>>(() =>
  Object.fromEntries(
    Object.entries(entries.value)
      .filter(([, entry]) => entry.layout)
      .map(([key, entry]) => [key, entry.layout as StanzaLayout]),
  ),
)

/** Estado de la nube, para el texto de Ajustes. */
export const stanzaEditsCloud = ref<'pendiente' | 'al-dia' | 'sin-conexion'>('pendiente')

let saveTimer = 0

/** Mismas estrofas con los mismos cambios (sin mirar el orden de las claves). */
function sameEntries(a: StanzaEditEntries, b: StanzaEditEntries): boolean {
  const keys = Object.keys(a)
  return keys.length === Object.keys(b).length && keys.every((key) => b[key]?.t === a[key].t)
}

/** Lee la nube y la fusiona con lo local. Devuelve lo que había en la nube ({} si el fichero aún no
 * existe), o null si no se pudo leer. */
async function fetchAndMergeRemote(): Promise<StanzaEditEntries | null> {
  try {
    // raw.githubusercontent.com cachea ~5 min en su CDN: el ?t= se lo salta (como canticos.json).
    const res = await fetch(`${STANZA_EDITS_RAW_URL}?t=${Date.now()}`, { cache: 'no-store' })
    if (res.status === 404) {
      return {}
    }
    if (!res.ok) {
      return null
    }
    const data = (await res.json()) as { repartos?: unknown }
    const remote = sanitizeStanzaEditEntries(data.repartos)
    const merged = mergeStanzaEditEntries(entries.value, remote)
    if (!sameEntries(merged, entries.value)) {
      entries.value = merged
      writeLocal(merged)
    }
    return remote
  } catch {
    return null
  }
}

/** Al abrir la app: trae lo de la nube y sube lo que este dispositivo tenga y la nube no. */
export async function loadRemoteStanzaEdits(): Promise<void> {
  const remote = await fetchAndMergeRemote()
  if (!remote) {
    stanzaEditsCloud.value = 'sin-conexion'
  } else if (!sameEntries(remote, entries.value)) {
    scheduleRemoteSave()
  } else {
    stanzaEditsCloud.value = 'al-dia'
  }
}

async function saveRemote(): Promise<void> {
  // Sin haber leído la nube no se escribe: el PUT sustituye el fichero entero y borraría lo de otros
  // dispositivos. Se lee (y fusiona) justo antes.
  if (!(await fetchAndMergeRemote())) {
    stanzaEditsCloud.value = 'sin-conexion'
    return
  }
  try {
    const res = await fetch(`${RELAY_URL}/repartos`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ repartos: entries.value }),
    })
    stanzaEditsCloud.value = res.ok ? 'al-dia' : 'sin-conexion'
  } catch {
    // Sin conexión: queda en este dispositivo; el próximo cambio o la próxima apertura lo sube.
    stanzaEditsCloud.value = 'sin-conexion'
  }
}

function scheduleRemoteSave(): void {
  if (typeof window === 'undefined') {
    return
  }
  stanzaEditsCloud.value = 'pendiente'
  window.clearTimeout(saveTimer)
  saveTimer = window.setTimeout(() => {
    saveTimer = 0
    void saveRemote()
  }, 1500)
}

/** «Guardar» de la hoja (14/11/2026): lo local ya está guardado; si hay una subida a la nube en espera,
 * sale ya en vez de esperar al temporizador. */
export function flushStanzaEditsSave(): void {
  if (typeof window === 'undefined' || stanzaEditsCloud.value !== 'pendiente' || !saveTimer) {
    return
  }
  window.clearTimeout(saveTimer)
  saveTimer = 0
  void saveRemote()
}

/** Guarda (o, con `undefined`, borra: «Restablecer estrofa») el reparto propio de una estrofa: al
 * instante aquí, y poco después en la nube. */
export function saveStanzaEdit(key: string, layout: StanzaLayout | undefined): void {
  const next = { ...entries.value, [key]: { layout: layout ?? null, t: Date.now() } }
  entries.value = next
  writeLocal(next)
  scheduleRemoteSave()
}
